const e=(d,h)=>({sv:d,en:h}),i="https://skatteverket.se/flytta",c="https://skatteverket.se/funktioner/svarpavanligafragor/privat/flyttning.4.18e1b10334ebe8bc8000705.html",b="https://www.skatteverket.se/privat/folkbokforing/flyttanmalan/anmalaflyttforbarn.4.3810a01c150939e893f18d24.html",M="https://www.skatteverket.se/privat/folkbokforing/flyttanmalan/sarskildpostadress.4.3aa8c78a1466c5845873561.html",f="https://www.skatteverket.se/foretag/skatterochavdrag/rotochrut/gerarbetetratttillrutavdrag.4.2ef18e6a125660db8b080001531.html",w="https://www.skatteverket.se/privat/fastigheterochbostad/forsaljningavbostad/raknautvinstforlustochskatt.4.233f91f71260075abe8800033595.html",E="https://www.skatteverket.se/privat/fastigheterochbostad/forsaljningavbostad/begaruppskov.4.6d02084411db6e252fe80009532.html",k="https://www.hyresgastforeningen.se/stod-och-rad/avtal-och-juridik/uppsagningstid-sa-funkar-det/",m="https://www.hyresgastforeningen.se/stod-och-rad/flytta/att-tanka-pa-nar-du-ska-flytta/",u="https://www.hyresgastforeningen.se/stod-och-rad/flytta/lagenhetsbesiktning--hur-gar-det-till/",j="https://www.hyresgastforeningen.se/stod-och-rad/lagenheten/jag-ska-flytta-till-min-forsta-hyresratt--vad-ar-viktigt-for-mig-att-veta/",S="https://www.konsumentverket.se/varor-och-tjanster/kopa-hus-tips/",L="https://www.konsumentverket.se/varor-och-tjanster/kopa-bostadsratt-tips/",A="https://www.konsumentverket.se/varor-och-tjanster/dolda-fel-i-hus/",p="https://www.konsumentverket.se/varor-och-tjanster/bindningstid-och-uppsagningstid/",l="https://www.hallakonsument.se/varor-och-tjanster/tips-infor-att-anlita-flyttfirma/",B="https://fmi.se/vad-galler-vid-formedling/maklarens-ansvar-och-roll/",v="https://fmi.se/vad-galler-vid-formedling/marknadsforing-och-visning/koparens-undersokningsplikt/",T="https://fmi.se/vad-galler-vid-formedling/budgivning/",r="https://fmi.se/vad-galler-vid-formedling/kontraktsskrivning/",Y="https://www.lantmateriet.se/sv/fastighet-och-mark/kopa-aga-salja-eller-ge-bort/Stampelskatt-och-avgifter/",N="https://www.lantmateriet.se/sv/fastighet-och-mark/kopa-aga-salja-eller-ge-bort/registrera-agare---lagfart/ansokan-vid-kop/",o="https://www.energimarknadsbyran.se/el/dina-elavtal-och-kostnader/elhandelsavtalet/sa-tecknas-elavtal/inga-eller-avsluta-avtal/utflyttning/",q="https://www.energimarknadsbyran.se/el/dina-elavtal-och-kostnader/elhandelsavtalet/sa-tecknas-elavtal/inga-eller-avsluta-avtal/inflyttning/",O="https://www.konsumenternas.se/forsakringar/boendeforsakringar/hemforsakringar/nar-galler-forsakringen/",s="https://www.konsumenternas.se/livssituationer/var-i-livet-befinner-du-dig/flytta-hemifran/flytten/",U="https://www.1177.se/sa-fungerar-varden/att-valja-vardmottagning/valja-vardmottagning/",y="https://www.forsakringskassan.se/privatperson/familj-och-barn/bostadsbidrag-for-barnfamiljer/meddela-andringar-om-bostadsbidraget",W="https://www.transportstyrelsen.se/sv/vagtrafik/fordon/aga-kopa-eller-salja-fordon/adresser-i-vagrafikregistret/",_="https://www.csn.se/om-nagot-hander-eller-andras/flyttar-eller-byter-adress.html",J="https://utbildningsguiden.skolverket.se/grundskolan/valja-grundskola/byta-grundskola---sa-har-fungerar-det",K="https://www.bostadsratterna.se/kunskapsbanken/m/medlemskapsprovning",z={code:"SE",currency:"SEK",native:"sv",languages:["sv","en"],reviewed:"2026-10-19",dateLocale:"sv-SE",propertyTypes:{Hus:e("Villa/radhus","House"),Ejerlejlighed:e("Ägarlägenhet","Owned flat"),Andel:e("Bostadsrätt","Tenant-owned flat"),Leje:e("Hyresrätt","Rental")},availableTypes:["Hus","Andel","Leje","Ejerlejlighed"],trackLabels:{buy:e("Mitt köp","My purchase"),sell:e("Min försäljning","My sale"),rentIn:e("Hyra · inflyttning","Renting · moving in"),rentOut:e("Hyra · utflyttning","Renting · moving out")},stages:[e("Förberedelse","Preparation"),e("Avtal & villkor","Contract & conditions"),e("Redo för tillträde","Ready for completion"),e("Avslut","Closing")],contextLabels:{buy:e("Köpet","The purchase"),sell:e("Försäljningen","The sale"),rentIn:e("Nya hyresrätten","New rental"),rentOut:e("Hyresrätten du lämnar","Rental you are leaving"),common:e("Själva flytten","The move itself"),incoming:e("Nya bostaden","New home"),outgoing:e("Tidigare bostaden","Previous home")},transport:{Selv:e("Själv","Myself"),Flyttefirma:e("Flyttfirma","Moving company")},address:{provider:"photon",country:"SE"},links:{citizen:i,consumer:l}},X=[["charging",e("Laddbox eller laddabonnemang","EV charger or charging subscription")],["children",e("Barn, skola eller förskola","Children, school or preschool")],["pets",e("Husdjur","Pets")],["car",e("Bil eller boendeparkering","Car or residential parking permit")],["alarm",e("Larm eller bevakningsabonnemang","Alarm or monitoring subscription")],["services",e("Serviceavtal, t.ex. fönsterputs, städ eller trädgård","Service contracts, e.g. window cleaning, cleaning or garden help")],["benefits",e("Bostadsbidrag, bostadstillägg eller andra ersättningar","Housing allowance or other public benefits")],["business",e("Företag registrerat på hemadressen","Business registered at the home address")],["care",e("Hemtjänst, hjälpmedel eller pågående behandling","Home care, aids or ongoing treatment")],["association",e("Bostadsrättsförening, samfällighet eller vägförening","Housing association, joint facility or road association")],["privacy",e("Skyddade personuppgifter","Protected personal data")],["proxy",e("Jag hjälper någon annan med flytten","I am helping someone else move")],["solar",e("Solceller eller annan egen elproduktion","Solar panels or other own electricity production")],["well",e("Egen brunn, enskilt avlopp eller egen värmeanläggning","Own well, private sewage or own heating system")],["student",e("Studier eller studiemedel från CSN","Studies or student finance from CSN")],["pension",e("Pension","Pension")],["firstHome",e("Första egna bostaden eller ändrat hushåll","First own home or changed household")],["special",e("Särskilda register eller tillstånd","Special registrations or permits")]],t={adress:e("Adress","Address"),halsa:e("Hälsa","Health"),ekonomi:e("Ekonomi","Finances"),forsakring:e("Försäkring","Insurance"),el:e("El, värme & vatten","Electricity, heating & water"),laddning:e("Laddning","Charging"),abonnemang:e("Abonnemang","Subscriptions"),bostad:e("Bostadsavtal","Housing contracts"),familj:e("Familj","Family"),transport:e("Transport","Transport"),packning:e("Packning","Packing"),tilltrade:e("Tillträde & avflyttning","Handover"),praktiskt:e("Praktiskt","Practical"),flyttdag:e("Flyttdagen","Moving day"),stad:e("Städning","Cleaning"),uppackning:e("Uppackning","Unpacking")},Q=[["address",e("Gör flyttanmälan till Skatteverket","Report your move to Skatteverket"),-7,15,t.adress,e("Anmäl gratis i e-tjänsten Flyttanmälan med e-legitimation. Gör det före flytten eller senast en vecka efter att du flyttat in – då gäller nya adressen från inflyttningsdagen. Anmäler du senare gäller adressen först från den dag Skatteverket tar emot anmälan. Uppge lägenhetsnummer om du flyttar till flerbostadshus. Spara kvittensen.","Report for free in the Flyttanmälan e-service with e-ID. Do it before the move or at the latest one week after moving in – then the new address applies from the day you moved in. If you report later, it applies only from the day Skatteverket receives it. Give the apartment number if you move into a block of flats. Keep the receipt."),null,"date",i],["address-confirm",e("Kontrollera att folkbokföringen är uppdaterad","Check that your registered address is updated"),7,10,t.adress,e("Logga in hos Skatteverket och kontrollera adress, datum och vilka personer som omfattas. Skatteverket skickar din nya adress vidare till de flesta myndigheter, men inte till privatpersoner eller alla företag.","Log in at Skatteverket and check the address, date and who is covered. Skatteverket passes the new address to most authorities, but not to private individuals or every company."),null,"date",c],["mail-forward",e("Beställ eftersändning av post via Svensk Adressändring","Order mail forwarding via Svensk Adressändring"),-14,15,t.adress,e("Flyttanmälan hos Skatteverket flyttar inte din post. Eftersändning beställs separat hos Svensk Adressändring (adressandring.se) mot avgift, normalt för upp till ett år. Beställ i god tid så att den börjar gälla på flyttdagen.","The move report to Skatteverket does not forward your mail. Forwarding is ordered separately from Svensk Adressändring (adressandring.se) for a fee, normally for up to a year. Order in good time so it starts on moving day."),null,"date",c],["mailbox",e("Sätt namn på postlåda, dörr och porttelefon","Put your name on the mailbox, door and entry phone"),0,15,t.adress,e("Sätt hushållets namn på nya adressen och avtala med hyresvärd eller förening om namnskylt i porten. Ta bort namnet på den gamla adressen.","Put the household's names at the new address and agree with the landlord or association about the name plate at the entrance. Remove your name at the old address.")],["senders",e("Uppdatera adress hos avsändare och i leveransprofiler","Update your address with senders and delivery profiles"),-7,25,t.adress,e("Gå igenom e-handel, paketombud, matkassar, tidningar och prenumerationer. Kontrollera öppna beställningar till den gamla adressen. Företag får inte automatiskt din nya adress från Skatteverket om de inte hämtar från SPAR.","Go through online shops, parcel pick-up, meal boxes, newspapers and subscriptions. Check open orders to the old address. Companies do not automatically get your new address unless they use the SPAR register.")],["employer",e("Meddela arbetsgivare och eventuellt lärosäte","Notify your employer and any place of study"),-14,15,t.adress,e("Kontrollera adress i lönesystem, personalregister och avtal om t.ex. hemarbetsplats eller förmånsbil. Ändrat pendlingsavstånd kan påverka reseavdraget i deklarationen.","Check your address in the payroll system, staff records and any agreements about home office or company car. A changed commute may affect your travel deduction in the tax return.")],["privacy",e("Hantera skyddade personuppgifter vid flytten","Handle protected personal data when moving"),-21,20,t.adress,e("Har du sekretessmarkering eller skyddad folkbokföring: kontakta Skatteverket innan du anmäler flytt och följ deras anvisningar. Lämna inte ut nya adressen i onödan till företag och föreningar.","If you have a confidentiality marking or protected registration: contact Skatteverket before reporting the move and follow their instructions. Do not give the new address to companies and associations unnecessarily."),"privacy","date",i],["proxy",e("Ordna fullmakt om du hjälper någon annan","Arrange power of attorney if you are helping someone else"),-42,25,t.adress,e("Flyttanmälan görs med personens egen e-legitimation eller på blankett SKV 7845 med underskrift. Kontrollera vilka fullmakter bank, hyresvärd och elbolag kräver. Åtkomst till appen är ingen juridisk fullmakt.","The move report is made with the person's own e-ID or on form SKV 7845 with signature. Check which powers of attorney the bank, landlord and electricity companies require. Access to the app is not a legal power of attorney."),"proxy","date",c],["special-postadress",e("Ta ställning till särskild postadress","Decide whether you need a special postal address"),-14,10,t.adress,e("Vill du få posten till en annan adress än folkbokföringsadressen i minst sex månader kan du gratis registrera särskild postadress hos Skatteverket. Den upphör inte automatiskt när du flyttar – kontrollera att en gammal registrering inte ligger kvar.","If you want mail sent to an address other than your registered one for at least six months, you can register a special postal address with Skatteverket for free. It does not end automatically when you move – check that an old registration is not still active."),null,"date",M],["address-followup",e("Följ upp post och avtal som fortfarande använder gamla adressen","Follow up on mail and contracts still using the old address"),21,15,t.adress,e("Rätta avsändare och profiler du missat och spara nödvändiga bekräftelser. Eftersändningen är tidsbegränsad.","Correct senders and profiles you missed and keep the confirmations you need. Mail forwarding is time-limited.")],["ad-preferences",e("Se över reklamval och kontaktinställningar på nya adressen","Review advertising choices and contact settings at the new address"),7,10,t.adress,e("Uppdatera NIX-spärrar, 'Ingen reklam'-skylt och samtycken hos företag om du vill.","Update NIX blocks, the 'no advertising' sign and consents with companies if you wish.")],["special",e("Kontrollera särskilda register, licenser och tillstånd","Check special registers, licences and permits"),-28,25,t.adress,e("Gå igenom t.ex. vapenlicens, jakt- och fiskekort, båtregister eller andra adressberoende tillstånd. Kontakta ansvarig myndighet om vad som krävs.","Go through e.g. firearms licence, hunting and fishing permits, boat register or other address-dependent permits. Contact the responsible authority about what is required."),"special"],["doctor",e("Välj vårdcentral i den nya regionen","Choose a health centre in the new region"),-14,15,t.halsa,e("Du kan lista dig på valfri vårdcentral i Sverige, oftast via 1177.se. I vissa regioner listas du automatiskt på närmaste om du inte väljer. Du får byta högst två gånger per år om det inte finns särskilda skäl. Kontrollera även fast läkarkontakt.","You can list at any health centre in Sweden, usually via 1177.se. In some regions you are listed automatically at the nearest one if you do not choose. You can switch at most twice a year unless there are special reasons. Check your named doctor too."),null,"date",U],["healthcard",e("Kontrollera uppgifter på 1177 och hos apoteket","Check your details on 1177 and at the pharmacy"),14,10,t.halsa,e("Kontrollera kontaktuppgifter i 1177 e-tjänster, att recept följer med och att eventuella hjälpmedelsleveranser går till nya adressen.","Check contact details in the 1177 e-services, that prescriptions follow you and that any aids are delivered to the new address.")],["dentist",e("Meddela tandläkare och andra vårdgivare","Notify your dentist and other care providers"),-7,15,t.halsa,e("Gå igenom tandvård, fysioterapeut, specialistmottagning och andra kontakter. Tandvården väljer du själv och den följer inte automatiskt med folkbokföringen.","Go through dental care, physiotherapist, specialist clinics and other contacts. You choose your dentist yourself; it does not follow the registration automatically.")],["medicine",e("Ordna medicin och nödvändig utrustning för flyttdagarna","Arrange medicine and essential equipment for the moving days"),-7,15,t.halsa,e("Packa medicin, recept, glasögon och viktig utrustning så att det finns tillgängligt under flytten.","Pack medicine, prescriptions, glasses and important equipment so they are at hand during the move.")],["care",e("Samordna hemtjänst, hjälpmedel och behandling","Coordinate home care, aids and treatment"),-42,35,t.halsa,e("Biståndsbeslut gäller i den kommun som fattat dem. Kontakta ny och gammal kommun samt vårdgivare i god tid om överlämning, leverans av hjälpmedel och startdatum, så att hjälpen inte avbryts.","Care decisions apply in the municipality that made them. Contact the new and old municipality and care providers in good time about handover, delivery of aids and start date so care is not interrupted."),"care"],["bank",e("Kontrollera adress hos bank, pensionsbolag och fackförbund","Check your address with bank, pension companies and union"),-7,15,t.ekonomi,e("Banker och många bolag hämtar adress från SPAR, men kontrollera uppgifter och meddelanden hos bank, pensionsbolag, a-kassa och fackförbund.","Banks and many companies take the address from SPAR, but check details and messages with bank, pension companies, unemployment fund and union.")],["tax",e("Se över deklarationen vid ändrade förhållanden","Review your tax situation after the change"),14,25,t.ekonomi,e("Undersök om reseavdrag, ränteavdrag eller rutavdrag för flytt och flyttstädning påverkar dig. Säljer du bostad deklareras försäljningen året efter att kontraktet skrevs.","Check whether travel deductions, interest deductions or RUT deductions for moving and cleaning affect you. If you sell a home, the sale is declared the year after the contract was signed."),null,"date",w],["benefits",e("Meddela ändrade bostadsförhållanden till Försäkringskassan","Report changed housing to Försäkringskassan"),-21,25,t.ekonomi,e("Har du bostadsbidrag eller bostadstillägg ska du anmäla direkt när du vet att du flyttar, att någon flyttar in eller ut eller att bostadskostnaden ändras. För mycket utbetalt bidrag måste betalas tillbaka med sanktionsavgift.","If you receive housing allowance or housing supplement, report as soon as you know you are moving, that someone moves in or out, or that housing costs change. Overpaid allowance must be repaid with a penalty fee."),"benefits","date",y],["housing-benefit",e("Undersök bostadsbidrag på nya adressen","Check housing allowance at the new address"),-21,25,t.ekonomi,e("Bidraget beräknas på bostadskostnad, boyta och hushåll. Rapporterar du en hyreshöjning inom 31 dagar kan höjningen gälla retroaktivt. Ansök på nytt om du inte redan har bidrag.","The allowance is based on housing cost, floor area and household. If you report a rent increase within 31 days, it can apply retroactively. Apply anew if you do not already receive it."),"benefits","date",y],["student",e("Kontrollera CSN och folkbokföring som student","Check CSN and registration as a student"),-21,20,t.ekonomi,e("Flyttar du för att studera på högskola ska du normalt folkbokföra dig på studieorten. CSN får din folkbokföringsadress automatiskt, men tillfällig adress och utlandsadress måste du anmäla själv.","If you move to study at university you should normally register at the place of study. CSN gets your registered address automatically, but a temporary or foreign address must be reported by you."),"student","date",_],["pension",e("Kontrollera pension och bostadstillägg vid ändrat boende","Check pension and housing supplement after the move"),-21,20,t.ekonomi,e("Pensionsmyndigheten får ny adress via folkbokföringen, men bostadstillägg beräknas på bostadskostnaden och måste anmälas vid ändring.","The Pensions Agency gets your new address via registration, but housing supplement is based on housing cost and changes must be reported."),"pension"],["business",e("Uppdatera företagsadress och företagsavtal","Update business address and business contracts"),-14,30,t.ekonomi,e("Enskild firma följer din folkbokföringsadress; aktiebolag ändras hos Bolagsverket. Kontrollera företagsförsäkring, fakturering, webbplats och om verksamhet är tillåten i nya bostaden (hyresvärd/förening).","A sole proprietorship follows your registered address; a limited company is changed at Bolagsverket. Check business insurance, invoicing, website and whether the activity is allowed in the new home (landlord/association)."),"business"],["first-home",e("Reda ut gemensam ekonomi, bohag och försäkring","Sort out shared finances, belongings and insurance"),-35,30,t.ekonomi,e("Kom överens om betalningar, vem som äger vad och vilka försäkringar och abonnemang som ska fortsätta. Sambo omfattas ofta av hemförsäkringen om ni är folkbokförda på samma adress, men kontrollera villkoren.","Agree on payments, who owns what and which insurance and subscriptions continue. A cohabiting partner is often covered by the home insurance if registered at the same address, but check the terms."),"firstHome","date",O],["payments",e("Kontrollera gamla och nya fasta betalningar","Check old and new recurring payments"),30,25,t.ekonomi,e("Gå igenom autogiron och e-fakturor efter dubbla debiteringar, oavslutade abonnemang och uteblivna återbetalningar. Avsluta betalningsavtal först när slutfakturan är klar.","Go through direct debits and e-invoices for double charges, unfinished subscriptions and missing refunds. End payment agreements only when the final invoice is settled.")],["moving-support",e("Undersök ekonomisk hjälp till flytt eller hyra","Check financial help with the move or rent"),-70,25,t.ekonomi,e("Behöver du stöd till flyttkostnad eller deposition kan ekonomiskt bistånd prövas av kommunen. Kontakta socialtjänsten innan du ingår avtal eller tar på dig kostnader.","If you need help with moving costs or a deposit, the municipality can assess financial assistance. Contact social services before you sign contracts or take on costs."),"benefits"],["insurance",e("Flytta hemförsäkringen och täck båda bostäderna","Move your home insurance and cover both homes"),-28,30,t.forsakring,e("Kontakta försäkringsbolaget så att skyddet gäller från inflyttningsdagen. Många hemförsäkringar har ett flyttskydd som täcker både gamla och nya adressen i 14–45 dagar och ibland sakerna under transport – kontrollera vad som gäller för dig. Spara svaret.","Contact your insurer so cover applies from the day you move in. Many home policies include a moving cover for both the old and new address for 14–45 days and sometimes belongings in transit – check what applies to you. Keep the reply."),null,"date",s],["houseinsurance",e("Teckna villaförsäkring eller bostadsrättstillägg","Take out house insurance or the tenant-owner add-on"),-28,30,t.forsakring,e("Villa kräver villahemförsäkring från tillträdesdagen. Bostadsrätt kräver hemförsäkring med bostadsrättstillägg, som täcker det du ansvarar för enligt föreningens stadgar. Bekräfta startdatum skriftligt.","A house needs house-and-home insurance from the completion date. A bostadsrätt needs home insurance with the tenant-owner add-on, covering what you are responsible for under the association's bylaws. Confirm the start date in writing."),"owner","accessDate",s],["electric-old",e("Säg upp elnäts- och elhandelsavtal på gamla adressen","End grid and electricity supply contracts at the old address"),-35,20,t.el,e("Både elnätsavtalet och elhandelsavtalet måste avslutas – en adressändring räcker inte. Elnätsföretaget vill ofta ha besked minst en månad före, elhandlaren ofta minst 14 dagar före. Betalningsansvaret kvarstår tills avtalen är avslutade. Spara bekräftelsen.","Both the grid contract and the supply contract must be ended – an address change is not enough. The grid company often wants at least one month's notice, the supplier often at least 14 days. You remain liable until the contracts are ended. Keep the confirmation."),null,"exitDate",o],["electric-new",e("Teckna elnätsavtal och välj elhandelsavtal för nya bostaden","Sign a grid contract and choose a supplier for the new home"),-21,20,t.el,e("Elnätsföretaget bestäms av var bostaden ligger; elhandlare väljer du fritt. Teckna i god tid så att elen fungerar från tillträdet. Väljer du ingen elhandlare får du ett anvisat avtal som ofta är dyrare. Jämför priser innan du väljer.","The grid company is determined by where the home is; you choose the supplier freely. Sign in good time so power works from completion. If you choose no supplier you get an assigned contract, often more expensive. Compare prices before choosing."),null,"accessDate",q],["heat-old",e("Avsluta fjärrvärme, pellets eller annan värmeleverans","End district heating or other heating supply"),-28,20,t.el,e("Bor du i villa med fjärrvärme ska avtalet överlåtas eller avslutas vid tillträdet. I lägenhet ingår värmen oftast i hyran eller avgiften. Avtala slutdatum och avläsning.","In a house with district heating the contract is transferred or ended at completion. In a flat, heating is usually included in rent or fee. Agree the end date and meter reading."),"seller","exitDate"],["heat-new",e("Ta reda på hur nya bostaden värms och vem du avtalar med","Find out how the new home is heated and who you contract with"),-21,20,t.el,e("Fjärrvärme, värmepump, pellets eller direktverkande el? Överta eventuellt fjärrvärmeavtal från tillträdesdagen och ta reda på service- och sotningsintervall.","District heating, heat pump, pellets or direct electric heating? Take over any district heating contract from completion and find out service and chimney-sweeping intervals."),"owner","accessDate"],["water",e("Anmäl ägarbyte för vatten, avlopp och sophämtning till kommunen","Report change of owner for water, sewage and waste to the municipality"),-21,15,t.el,e("För villa sköts VA och avfall av kommunen eller det kommunala bolaget; anmäl ägarbyte med avläsning på tillträdesdagen. I lägenhet ingår detta normalt i hyran eller avgiften.","For a house, water and waste are handled by the municipality or its company; report the change of owner with a meter reading on completion day. In a flat this is normally included in rent or fee."),"owner","accessDate"],["meter-old",e("Fotografera och notera mätarställningar vid avflyttning","Photograph and note meter readings when leaving"),0,20,t.el,e("Spara mätarnummer, ställning, datum och foton för el, vatten och värme där det är relevant. Elnätsföretaget läser normalt av fjärrmätaren, men ditt foto är bra bevis.","Keep meter number, reading, date and photos for electricity, water and heating where relevant. The grid company normally reads the smart meter, but your photo is good evidence."),null,"exitDate",o],["meter-new",e("Fotografera och notera mätarställningar vid tillträde","Photograph and note meter readings at completion"),0,20,t.el,e("Spara startställning, datum och foton. Jämför med tillträdesprotokollet och avtala vem som rapporterar till vilka bolag.","Keep the starting reading, date and photos. Compare with the handover notes and agree who reports to which companies."),null,"accessDate"],["final-bills",e("Kontrollera slutfakturor för el, vatten och värme","Check final invoices for electricity, water and heating"),30,20,t.el,e("Jämför perioder, mätarställningar och preliminära debiteringar. Följ upp återbetalningar eller oväntade avgifter, t.ex. flyttavgift från elnätsföretaget.","Compare periods, meter readings and preliminary charges. Follow up refunds or unexpected fees, e.g. a moving fee from the grid company."),null,"exitDate",o],["solar",e("Överlåt eller avsluta avtal om solceller och elproduktion","Transfer or end contracts for solar panels and electricity production"),-42,30,t.el,e("Kontakta elhandlaren om avtalet för såld el, elnätsföretaget om produktionsanläggningen och Skatteverket om skattereduktion för mikroproduktion. Avtala vad som gäller från tillträdet.","Contact the supplier about the contract for sold electricity, the grid company about the production facility and Skatteverket about the tax reduction for micro-production. Agree what applies from completion."),"solar"],["well",e("Ta hand om egen brunn, enskilt avlopp och värmeanläggning","Take care of own well, private sewage and heating system"),-35,30,t.el,e("Samla tillstånd för enskilt avlopp, senaste vattenprov, slamtömningsavtal och servicehistorik för panna eller värmepump. Kommunens miljökontor kan ha krav på avloppet. Lämna över dokumenten vid tillträdet.","Collect the permit for private sewage, latest water test, sludge emptying contract and service history for boiler or heat pump. The municipal environmental office may have requirements for the sewage. Hand over the documents at completion."),"well","date",S],["charge-contract",e("Säg upp, flytta eller överlåt laddabonnemanget","Cancel, move or transfer the charging subscription"),-42,30,t.laddning,e("Ta reda på leverantör, kundnummer, bindningstid och uppsägningstid. Fråga om kostnad för uppsägning, flytt eller överlåtelse. Spara skriftligt besked och slutdatum.","Find the provider, customer number, binding period and notice period. Ask what cancellation, moving or transfer costs. Keep the written reply and end date."),"charging"],["charge-box",e("Avtala demontering, retur eller överlåtelse av laddboxen","Agree removal, return or transfer of the charging box"),-28,25,t.laddning,e("Klargör ägande/hyra, vem som får demontera, returfrakt, tillbehör och kostnader. Låt behörig elektriker sköta installationen.","Clarify ownership/lease, who may remove it, return shipping, accessories and costs. Let a qualified electrician handle the installation."),"charging"],["charge-new",e("Planera laddlösning på nya adressen","Plan a charging solution at the new address"),-35,30,t.laddning,e("Undersök befintlig installation, elens kapacitet och om bostadsrättsföreningen eller samfälligheten har regler för laddplatser. Ta in offerter och boka installation.","Check the existing installation, electrical capacity and whether the housing association or joint facility has rules for charging spots. Get quotes and book installation."),"charging","accessDate"],["charge-end",e("Kontrollera att laddavtalet avslutats och sista betalningen","Check that the charging contract has ended and the final payment"),14,15,t.laddning,e("Spara kvitto på returnerad utrustning, bekräftad uppsägning och slutfaktura.","Keep the receipt for returned equipment, confirmed cancellation and the final invoice."),"charging","exitDate"],["internet",e("Flytta eller teckna nytt bredband","Move or sign up for new broadband"),-42,25,t.abonnemang,e("Kontrollera vilka nät som finns på nya adressen (fiber, stadsnät, kabel, mobilt). Bindningstid får vara högst 24 månader och uppsägningstid högst en månad, men du betalar bindningstiden ut även om du flyttar. Fråga om flytt av abonnemanget innan du säger upp.","Check which networks exist at the new address (fibre, city network, cable, mobile). Binding period may be at most 24 months and notice period at most one month, but you pay out the binding period even if you move. Ask about moving the subscription before you cancel."),null,"accessDate",p],["router",e("Lämna tillbaka lånad router, tv-box och annan utrustning","Return the borrowed router, TV box and other equipment"),3,20,t.abonnemang,e("Be om returinstruktioner och sista datum från operatören. Fotografera serienummer och spara inlämningskvittot.","Ask the operator for return instructions and the deadline. Photograph serial numbers and keep the receipt."),null,"exitDate"],["subscriptions",e("Gå igenom tv, streaming, mobil, tidningar och övriga abonnemang","Review TV, streaming, mobile, newspapers and other subscriptions"),-28,30,t.abonnemang,e("Välj behåll, flytta eller säg upp för varje avtal. Säg upp skriftligt och be om bekräftelse. En flytt säger inte upp dina avtal åt dig.","Choose keep, move or cancel for each contract. Cancel in writing and ask for confirmation. Moving does not cancel your contracts for you."),null,"date",p],["memberships",e("Flytta eller säg upp gym och lokala medlemskap","Move or cancel gym and local memberships"),-35,20,t.abonnemang,e("Gå igenom träning, föreningar, bibliotek och lokala klubbar. Bekräfta uppsägningstider och eventuella nya medlemskap.","Go through gym, associations, library and local clubs. Confirm notice periods and any new memberships.")],["alarm",e("Flytta eller säg upp larm och bevakningsavtal","Move or cancel alarm and monitoring contracts"),-42,25,t.abonnemang,e("Klargör utrustning, väktaravtal, abonnemang, koder och överlåtelse. Ta bort gamla gäståtkomster enligt överenskommelse.","Clarify equipment, guard contract, subscription, codes and transfer. Remove old guest access as agreed."),"alarm"],["services",e("Flytta eller avsluta fasta serviceavtal","Move or end regular service contracts"),-35,25,t.abonnemang,e("Gå igenom fönsterputs, städ, trädgård, snöröjning, sotning, ventilationsservice och andra avtal som gäller bostaden. Rutavdrag kan påverkas av vem som är beställare.","Go through window cleaning, cleaning, garden, snow removal, chimney sweeping, ventilation service and other contracts tied to the home. RUT deductions may depend on who is the customer."),"services"],["tenancy-end",e("Säg upp hyresavtalet skriftligt i tid","Give written notice on the tenancy in time"),-100,30,t.bostad,e("Vanlig uppsägningstid är tre hela kalendermånader: säger du upp den 8 september gäller avtalet till och med 31 december. Säg upp skriftligt, gärna rekommenderat, och be om bekräftelse. Datumet här är en planeringshjälp – kontrollera ditt avtal.","The usual notice period is three full calendar months: if you give notice on 8 September the contract runs until 31 December. Give notice in writing, preferably by registered letter, and ask for confirmation. The date here is a planning aid – check your contract."),"renter","exitDate",k],["tenancy-inspection",e("Boka avflyttningsbesiktning och dokumentera lägenhetens skick","Book the move-out inspection and document the flat's condition"),-21,25,t.bostad,e("Hyresvärden bör besiktiga vid avflyttning; be att få vara med och få en kopia av protokollet. Ta fram inflyttningsprotokollet och fotografera eller filma. Du betalar inte för normalt slitage, men för skador du orsakat.","The landlord should inspect at move-out; ask to attend and get a copy of the protocol. Bring out the move-in protocol and photograph or film. You do not pay for normal wear, but for damage you caused."),"renter","exitDate",u],["deposit",e("Följ upp deposition och eventuella krav från hyresvärden","Follow up on the deposit and any claims from the landlord"),28,20,t.bostad,e("Deposition är ovanligt vid förstahandskontrakt men förekommer vid andrahand och privat uthyrning. Be om återbetalning skriftligt. Hyresvärden måste bevisa skador och kan ställa krav upp till två år efter avflyttning – spara foton och protokoll.","Deposits are uncommon for first-hand tenancies but occur with sublets and private landlords. Request the refund in writing. The landlord must prove damage and can make claims up to two years after you move out – keep photos and protocols."),"renter","exitDate",m],["new-rent",e("Gå igenom nya hyresavtalet, betalningar och inflyttningsprotokoll","Review the new tenancy, payments and move-in protocol"),-21,30,t.bostad,e("Du har rätt till skriftligt avtal. Be om kopia av besiktningsprotokollet från förra hyresgästen och anmäl skriftligt skador som inte finns med. Tillträde är normalt kl. 12 på avtalets första dag, nästa vardag om den infaller på helg.","You are entitled to a written contract. Ask for a copy of the inspection protocol from the previous tenant and report in writing any damage not listed. Access is normally at noon on the first day, the next weekday if it falls on a weekend."),"newRenter","accessDate",j],["owner-papers",e("Samla köpekontrakt, finansiering och tillträdesplan","Collect the purchase contract, financing and completion plan"),-35,40,t.bostad,e("Gå igenom med banken: slutbetalning, pantbrev eller pantsättning, lagfart och vad som sker på tillträdesdagen. Samla kontrakt, nycklar, lösöre och protokoll på ett ställe.","Go through with the bank: final payment, mortgage deeds or pledge, title registration and what happens on completion day. Keep contract, keys, fixtures list and protocols in one place."),"owner","accessDate",r],["sale-papers",e("Klargör vad som ska lämnas vid försäljningen","Clarify what must be handed over at the sale"),-28,30,t.bostad,e("Gå igenom med mäklaren: lösöre som ingår, städning, nycklar, mätaravläsning, manualer och tid för tillträde. Kontrollera vad kontraktet lovar.","Go through with the agent: fixtures included, cleaning, keys, meter readings, manuals and time of completion. Check what the contract promises."),"seller","exitDate",r],["association",e("Meddela bostadsrättsförening, samfällighet eller vägförening","Notify the housing association, joint facility or road association"),-28,20,t.bostad,e("Klargör kontaktperson, avgifter, in- och utflyttningsregler, nyckelbrickor, tvättstuga, förråd och parkering. Vid bostadsrätt krävs medlemskapsansökan till styrelsen.","Clarify contact person, fees, move-in/out rules, key fobs, laundry room, storage and parking. For a bostadsrätt a membership application to the board is required."),"association","date",K],["children-school",e("Ordna skola, fritids och förskola i nya kommunen","Arrange school, after-school care and preschool in the new municipality"),-56,35,t.familj,e("Kontakta nya kommunen om skolplacering och förskoleplats – rutiner, ansökningsperioder och köer varierar. Båda vårdnadshavarna ska skriva under ansökan. Nuvarande skola skickar över betyg och underlag till den nya.","Contact the new municipality about school placement and preschool – procedures, application periods and queues vary. Both guardians must sign the application. The current school sends grades and records to the new one."),"children","date",J],["children-address",e("Anmäl barnets flytt och ordna samtycke","Report the child's move and arrange consent"),-14,20,t.familj,e("Ett barn folkbokförs där det sover flest nätter. Flyttar ni tillsammans anmäler en vårdnadshavare för hela familjen. Bor vårdnadshavarna isär ska den andra lämna samtycke i e-tjänsten inom sju dagar, annars utreder Skatteverket.","A child is registered where it sleeps most nights. If you move together, one guardian reports for the whole family. If guardians live apart, the other must give consent in the e-service within seven days, otherwise Skatteverket investigates."),"children","date",b],["children-day",e("Planera barnpassning och barnens första kväll","Plan childcare and the children's first evening"),-14,20,t.familj,e("Ordna passning på flyttdagen, transport, mat och en lättåtkomlig låda med kända saker.","Arrange care on moving day, transport, food and an easily reached box of familiar things."),"children"],["children-activities",e("Flytta fritidsaktiviteter och skolskjuts","Move leisure activities and school transport"),-28,20,t.familj,e("Gå igenom träningsgrupper, kulturskola, skolskjuts och kontaktuppgifter. Notera utträdes- och startdatum.","Go through sports groups, music school, school transport and contact details. Note leaving and start dates."),"children"],["pets-register",e("Uppdatera husdjurens register och avtal","Update the pets' registers and contracts"),-7,20,t.familj,e("Hund ska vara registrerad hos Jordbruksverket med ägarens adress; uppdatera chip-register, försäkring och veterinär. Undersök nya kommunens regler för t.ex. hundrastgårdar.","Dogs must be registered with Jordbruksverket with the owner's address; update chip register, insurance and vet. Check the new municipality's rules for e.g. dog parks."),"pets"],["pets-day",e("Ordna passning och trygg transport av husdjur","Arrange care and safe transport for pets"),-14,20,t.familj,e("Planera transport, mat, medicin och ett lugnt rum. Håll djuren borta från öppna dörrar under flytten.","Plan transport, food, medicine and a quiet room. Keep animals away from open doors during the move."),"pets"],["car",e("Kontrollera bilförsäkring, boendeparkering och garage","Check car insurance, residential parking and garage"),-21,25,t.transport,e("Vägtrafikregistret uppdateras automatiskt när du gör flyttanmälan. Boendeparkering söks hos kommunen och kräver normalt att du är folkbokförd på adressen och äger bilen. Säg upp gammal p-plats och kontrollera försäkringens zon.","The vehicle register is updated automatically when you report the move. Residential parking is applied for at the municipality and normally requires that you are registered at the address and own the car. Cancel the old parking space and check your insurance zone."),"car","date",W],["access",e("Planera tillfart, parkering och hiss för flyttbilen","Plan access, parking and lift for the moving van"),-21,20,t.transport,e("Klargör infart, gård, trappor, hissbokning och om du behöver tillfällig dispens eller parkeringstillstånd från kommunen.","Clarify driveway, courtyard, stairs, lift booking and whether you need a temporary exemption or parking permit from the municipality.")],["movers-contract",e("Kontrollera flyttfirmans pris, omfattning och försäkring","Check the moving company's price, scope and insurance"),-21,30,t.transport,e("Ta skriftlig offert, helst fast pris – vid ungefärligt pris får slutpriset bli högst 15 % högre. Välj firma som följer Bohag 2010 och har yrkestrafiktillstånd. Flytthjälp ger rutavdrag på 50 % av arbetskostnaden.","Get a written quote, preferably a fixed price – with an approximate price the final cost may be at most 15% higher. Choose a company that follows Bohag 2010 and holds a transport licence. Moving help qualifies for a 50% RUT deduction on labour."),"movers","date",l],["commute",e("Planera ny resväg till jobb, studier och aktiviteter","Plan the new route to work, studies and activities"),-14,20,t.transport,e("Prova rutter och se över periodkort. Längre pendling kan ge reseavdrag i deklarationen; kontrollera reglerna hos Skatteverket.","Try routes and review travel passes. A longer commute may qualify for a travel deduction; check the rules with Skatteverket.")],["measure",e("Mät dörrar, trappor och stora möbler","Measure doors, stairs and large furniture"),-28,30,t.packning,e("Kontrollera att stora saker får plats. Planera demontering, skydd och placering i nya bostaden.","Check that large items fit. Plan disassembly, protection and placement in the new home.")],["waste",e("Planera återbruk, donationer och grovsopor","Plan reuse, donations and bulky waste"),-28,25,t.packning,e("Boka hämtning vid behov och kontrollera kommunens återvinningscentral, öppettider och eventuella besöksbegränsningar.","Book collection if needed and check the municipal recycling centre, opening hours and any visit limits.")],["packing-supplies",e("Skaffa kartonger, skydd, etiketter och flyttutrustning","Get boxes, protection, labels and moving equipment"),-35,20,t.packning,e("Uppskatta antal och storlekar. Planera pirra, filtar, spännband, tejp och skydd för ömtåliga saker. Kartonger ingår inte i rutavdraget.","Estimate number and sizes. Plan a trolley, blankets, straps, tape and protection for fragile items. Boxes are not covered by the RUT deduction."),null,"date",f],["valuables",e("Packa värdesaker, viktiga papper och elektronik separat","Pack valuables, important papers and electronics separately"),-3,25,t.packning,e("Håll pass, nycklar, smycken, kontrakt och oersättliga saker under egen uppsikt. Säkerhetskopiera viktiga digitala filer.","Keep passports, keys, jewellery, contracts and irreplaceable things under your own supervision. Back up important digital files.")],["appliances",e("Förbered kyl, frys och vitvaror för transport","Prepare fridge, freezer and appliances for transport"),-3,30,t.packning,e("Planera matåtgång, avfrostning och rengöring. Koppla ur enligt tillverkarens anvisning och anlita fackman för fast installation.","Plan food use, defrosting and cleaning. Disconnect according to the manufacturer's instructions and use a professional for fixed installations.")],["loft",e("Töm vind, källare, förråd, garage och andra utrymmen","Empty attic, basement, storage, garage and other spaces"),-7,40,t.packning,e("Gå även igenom gemensamma utrymmen, cykelrum, lånade saker och sådant som står hos familj eller i magasin. Kontrollera vad som ska följa med bostaden.","Also go through shared spaces, bike rooms, borrowed items and things stored with family or in storage. Check what stays with the home.")],["plants",e("Planera säker transport av växter, vätskor och särskilda saker","Plan safe transport of plants, liquids and special items"),-7,20,t.packning,e("Kontrollera flyttfirmans regler och packa efter temperatur, vikt och läckagerisk. Transportera inte farligt gods utan anvisningar.","Check the moving company's rules and pack by temperature, weight and leak risk. Do not transport hazardous goods without instructions.")],["helpers-confirm",e("Bekräfta tid, roller och kontaktuppgifter med hjälpare","Confirm time, roles and contact details with helpers"),-3,15,t.flyttdag,e("Dela körschema och adresser. Kom överens om lyft, pauser, mat och vem som har nycklar till varje bostad. Vänners hemförsäkring kan täcka skador de orsakar.","Share the schedule and addresses. Agree on lifting, breaks, food and who holds keys to each home. Friends' home insurance may cover damage they cause."),null,"date",s],["damage",e("Gå igenom bohaget och dokumentera transportskador","Check belongings and document transport damage"),1,20,t.flyttdag,e("Fotografera skador och reklamera skriftligt till flyttfirman så snart som möjligt. Kontakta sedan försäkringsbolaget. Vid tvist kan ärendet prövas av ARN.","Photograph damage and complain in writing to the moving company as soon as possible. Then contact your insurer. Disputes can be referred to ARN."),null,"date",l],["keys-old",e("Samla alla nycklar, brickor och fjärrkontroller för överlämning","Collect all keys, fobs and remotes for handover"),-2,20,t.tilltrade,e("Hitta reservnycklar, postboxnyckel, tvättstuge- och förrådsnycklar, garageöppnare och taggar. Avtala och dokumentera antal och mottagare.","Find spare keys, mailbox key, laundry and storage keys, garage opener and tags. Agree and document number and recipient."),null,"exitDate"],["manuals",e("Lämna över manualer, servicepapper och avtalat lösöre","Hand over manuals, service records and agreed fixtures"),-7,20,t.tilltrade,e("Samla bruksanvisningar, garantier och servicehistorik för det som stannar i bostaden. Logga ut personliga konton från smarta hem-enheter.","Collect manuals, warranties and service history for what stays in the home. Log personal accounts out of smart-home devices.")],["empty-check",e("Ta slutfoton och kontrollera alla rum vid avflyttning","Take final photos and check every room when leaving"),0,25,t.tilltrade,e("Se över skåp, fönsterbrädor, balkong, förråd och tomt. Spara foton och bekräftelse på nycklar och överlämning – hyresvärden kan ställa krav upp till två år efteråt.","Check cupboards, window sills, balcony, storage and plot. Keep photos and confirmation of keys and handover – a landlord can make claims up to two years afterwards."),null,"exitDate",m],["safety",e("Hitta huvudkran, elcentral och testa brandvarnare","Find the main stopcock, fuse box and test smoke alarms"),1,20,t.tilltrade,e("Lär känna nya bostadens installationer. Hitta avstängningskranar och säkringar, kontrollera brandvarnare och brandsläckare och spara nödvändiga kontaktuppgifter.","Get to know the new home's installations. Find stopcocks and fuses, check smoke alarms and fire extinguisher and keep necessary contact details."),null,"accessDate"],["locks",e("Se över nycklar, lås och digitala åtkomster i nya bostaden","Review keys, locks and digital access in the new home"),1,20,t.tilltrade,e("Överväg byte av låscylinder efter överenskommelse med ägare eller hyresvärd. Återställ smarta hem-system och ordna åtkomst till port, post och gemensamma utrymmen.","Consider changing the lock cylinder in agreement with the owner or landlord. Reset smart-home systems and arrange access to entrance, mail and shared spaces."),null,"accessDate"],["handover-defects",e("Följ upp fel, brister och löften från tillträdet","Follow up on defects and promises from completion"),1,25,t.tilltrade,e("Samla dina iakttagelser och reklamera skriftligt till rätt motpart. Hyresrätt: till hyresvärden direkt. Köp: till säljaren inom skälig tid. Spara svaret och skapa uppföljningar.","Collect your observations and complain in writing to the right party. Rental: to the landlord straight away. Purchase: to the seller within reasonable time. Keep the reply and create follow-ups."),null,"accessDate",A],["waste-new",e("Ta reda på sophämtning och sortering på nya adressen","Find out waste collection and sorting at the new address"),3,15,t.praktiskt,e("Se vilka kärl och sorteringsregler som gäller, hämtningsdagar och närmaste återvinningsstation. Villaägare tecknar abonnemang hos kommunen.","See which bins and sorting rules apply, collection days and the nearest recycling station. House owners sign a subscription with the municipality.")],["neighbours",e("Informera grannar om flytt och tillfällig störning","Inform neighbours about the move and temporary disturbance"),-7,10,t.praktiskt,e("Kom överens om hänsyn till trapphus, hiss, parkering och ljud. Många föreningar har regler för flytt på helger och kvällar.","Agree on consideration for stairwell, lift, parking and noise. Many associations have rules for moving on weekends and evenings.")],["clean-final",e("Gör flyttstädning enligt hyresvärdens eller köparens krav","Do the move-out cleaning to the landlord's or buyer's standard"),-2,90,t.stad,e("Städa inklusive ugn, fläkt, avlopp, skåp, fönster, förråd och balkong. Anlitar du städfirma ger flyttstädning rutavdrag på 50 % av arbetskostnaden. Spara kvitton.","Clean including oven, extractor, drains, cupboards, windows, storage and balcony. If you hire a cleaning company, move-out cleaning qualifies for a 50% RUT deduction on labour. Keep receipts."),null,"exitDate",f],["packing-return",e("Lämna tillbaka lånade kartonger, nycklar och flyttutrustning","Return borrowed boxes, keys and moving equipment"),14,20,t.uppackning,e("Kontrollera returfrister och spara kvitton. Notera eventuell deposition som ska betalas tillbaka.","Check return deadlines and keep receipts. Note any deposit that should be refunded.")]],Z={rent:j,rentIn:u,rentOut:k,sale:B,contract:r,approval:T,settle:N,refund:w},g=["Hus","Ejerlejlighed"],$=[["buy",0,"budget",e("Skaffa lånelöfte och gör en boendekalkyl","Get a loan promise and a housing-cost calculation"),e("Du + bank","You + bank"),e("Banken ger lånelöfte utifrån inkomst och utgifter; det gäller en begränsad tid och banken kan ändå säga nej till en viss bostad. Du får låna högst 90 % av värdet – resten är kontantinsats. Räkna med lagfart, pantbrev, avgift eller driftskostnader och en buffert.","The bank gives a loan promise based on income and expenses; it is valid for a limited time and the bank can still refuse a specific home. You may borrow at most 90% of the value – the rest is a cash deposit. Budget for title registration, mortgage deeds, fees or running costs and a buffer."),e("Skriftligt lånelöfte och boendekalkyl","Written loan promise and housing-cost calculation"),"contract"],["buy",0,"advisor",e("Bestäm vilken hjälp du vill ha utöver mäklaren","Decide what help you want beyond the agent"),e("Du","You"),e("Mäklaren är en opartisk mellanman som anlitas av säljaren och ska bevaka säljarens pris. Vill du ha egen rådgivning: jurist för kontraktet, besiktningsman för skicket, banken för ekonomin. Avtala omfattning och pris i förväg.","The agent is an impartial intermediary hired by the seller and works for the seller's price. If you want your own advice: a lawyer for the contract, an inspector for the condition, the bank for the finances. Agree scope and price in advance."),e("Lista över rådgivare och uppdrag","List of advisers and assignments"),"sale"],["buy",0,"inspect",e("Läs objektsbeskrivning, frågelista och energideklaration","Read the property description, seller's questionnaire and energy declaration"),e("Du + mäklare","You + agent"),e("Mäklaren ska skriftligt informera om din undersökningsplikt och lämna objektsbeskrivning. Be om säljarens frågelista, planritning, tidigare besiktningsprotokoll och driftskostnader. Ställ frågor skriftligt och spara svaren.","The agent must inform you in writing of your duty to inspect and provide a property description. Ask for the seller's questionnaire, floor plan, earlier inspection protocols and running costs. Ask questions in writing and keep the answers."),e("Dokument och skriftliga svar","Documents and written answers"),"sale"],["buy",0,"association",e("Granska bostadsrättsföreningens ekonomi","Review the housing association's finances"),e("Du + bank","You + bank"),e("Läs årsredovisning, stadgar och styrelsens svar: skuldsättning, avgift, underhållsplan och planerade arbeten som stambyte eller tak. Låg avgift kan betyda eftersatt underhåll. Be om utdrag ur lägenhetsförteckningen för att se pantsättning.","Read the annual report, bylaws and the board's answers: debt, monthly fee, maintenance plan and planned work such as pipe replacement or roof. A low fee can mean neglected maintenance. Ask for an extract from the apartment register to see pledges."),e("Genomgången årsredovisning och svar från styrelsen","Reviewed annual report and answers from the board"),"contract",["Andel"]],["buy",0,"survey",e("Beställ egen besiktning innan du binder dig","Order your own inspection before you commit"),e("Du + besiktningsman","You + inspector"),e("Du har en långtgående undersökningsplikt för fastighet; fel du borde ha upptäckt kan du inte kräva ersättning för. En överlåtelsebesiktning täcker normalt inte el, VVS, eldstad, tomt eller radon – beställ tilläggskontroller vid behov. Går besiktning inte före kontraktet, kräv en besiktningsklausul.","You have a far-reaching duty to inspect a property; you cannot claim for defects you should have found. A transfer inspection normally excludes electrics, plumbing, fireplace, plot and radon – order extra checks if needed. If inspection cannot happen before contract, insist on an inspection clause."),e("Besiktningsprotokoll och eventuella tilläggskontroller","Inspection protocol and any extra checks"),"contract",g],["buy",0,"offer",e("Lägg bud och förstå budgivningen","Place a bid and understand the bidding"),e("Du + mäklare","You + agent"),e("Bud är inte bindande – varken för dig eller säljaren – förrän kontraktet är undertecknat av båda. Säljaren bestämmer fritt vem som får köpa och behöver inte välja högsta budet. Mäklaren ska föra alla bud vidare och föra budgivningslista som du får efter affären. Bestäm din maxgräns innan.","Bids are not binding – for you or the seller – until the contract is signed by both. The seller freely decides who may buy and need not pick the highest bid. The agent must relay all bids and keep a bid list you receive after the deal. Set your maximum beforehand."),e("Maxpris, bud och villkor","Maximum price, bid and conditions"),"approval"],["buy",1,"terms",e("Gå igenom köpekontraktet innan ni skriver under","Review the purchase contract before signing"),e("Du + mäklare/jurist","You + agent/lawyer"),e("Köpekontraktet ska vara skriftligt och ange fastighet eller lägenhet, parter, pris och att egendomen överlåts. Kontrollera tillträdesdag, handpenning, besiktnings- eller återgångsvillkor, lösöre och eventuella friskrivningar – mäklaren ska förklara dem. Affären är bindande först vid underskrift.","The contract must be written and state the property or flat, parties, price and that it is transferred. Check completion date, deposit, inspection or rescission clauses, fixtures and any disclaimers – the agent must explain them. The deal is binding only on signing."),e("Genomgången kontraktsversion","Reviewed contract version"),"contract"],["buy",1,"deposit",e("Betala handpenning till klientmedelskonto","Pay the deposit into the client account"),e("Du + bank","You + bank"),e("Handpenning betalas normalt inom några dagar efter kontraktet, ofta till mäklarens klientmedelskonto. Beloppet och datumet står i kontraktet. Bekräfta kontonummer via känd kanal innan du betalar.","The deposit is normally paid within a few days of contract, often into the agent's client account. Amount and date are in the contract. Confirm the account number through a known channel before paying."),e("Kvitto på handpenning","Receipt for the deposit"),"contract"],["buy",1,"conditions",e("Följ besiktningsklausul och andra villkor","Follow the inspection clause and other conditions"),e("Du + mäklare","You + agent"),e("Har kontraktet en besiktningsklausul eller lånevillkor gäller den exakta formuleringen, fristen och vem som ska få beskedet. Missar du fristen blir köpet bindande utan villkor. Meddela skriftligt och spara kvittens.","If the contract has an inspection clause or financing condition, the exact wording, deadline and recipient apply. Miss the deadline and the purchase becomes unconditional. Notify in writing and keep proof."),e("Bekräftade frister och skriftliga besked","Confirmed deadlines and written notices"),"approval"],["buy",1,"membership",e("Ansök om medlemskap i bostadsrättsföreningen","Apply for membership of the housing association"),e("Du + styrelse","You + board"),e("Köpet fullbordas först när styrelsen beviljat medlemskap. Styrelsen får bara neka undantagsvis, t.ex. vid stora obetalda boendeskulder eller ålderskrav i seniorförening. Ett avslag kan prövas av hyresnämnden. Skicka ansökan direkt efter kontraktet.","The purchase is completed only when the board grants membership. The board may refuse only exceptionally, e.g. large unpaid housing debts or age rules in a senior association. A refusal can be reviewed by the rent tribunal. Send the application right after contract."),e("Beslut om medlemskap","Membership decision"),"approval",["Andel"]],["buy",1,"fixtures",e("Avtala lösöre och utlovade arbeten skriftligt","Agree fixtures and promised work in writing"),e("Du + säljare","You + seller"),e("Lista exakt vad som ingår (vitvaror, lampor, gardiner, trädgårdsmaskiner) och vilket skick. Beskriv arbeten säljaren ska göra, hur de dokumenteras och när. Lägg listan som bilaga till kontraktet.","List exactly what is included (appliances, lamps, curtains, garden machines) and in what condition. Describe work the seller will do, how it is documented and when. Attach the list to the contract."),e("Bilaga med lösöre och arbeten","Annex with fixtures and work"),"contract"],["buy",2,"payment",e("Få bankens tillträdesplan bekräftad","Get the bank's completion plan confirmed"),e("Bank + mäklare","Bank + agent"),e("På tillträdesdagen betalar banken slutlikviden, säljarens lån löses och köpebrev skrivs. Bekräfta tid, plats och vilka handlingar som krävs. Betala aldrig till konton du fått via oväntade mejl.","On completion day the bank pays the balance, the seller's loans are redeemed and the bill of sale is signed. Confirm time, place and documents required. Never pay to accounts received via unexpected emails."),e("Bankens bekräftelse","The bank's confirmation"),"settle"],["buy",2,"deed",e("Ansök om lagfart och ordna pantbrev","Apply for title registration and arrange mortgage deeds"),e("Bank + du","Bank + you"),e("Lagfart söks hos Lantmäteriet inom tre månader efter köpet; banken sköter det oftast. Stämpelskatt är 1,5 % av det högsta av köpeskilling och taxeringsvärde plus expeditionsavgift 825 kr. Nya pantbrev kostar 2 % av beloppet plus 375 kr per pantbrev.","Title is applied for at Lantmäteriet within three months of purchase; the bank usually handles it. Stamp duty is 1.5% of the higher of price and assessed value plus an 825 SEK fee. New mortgage deeds cost 2% of the amount plus 375 SEK each."),e("Lagfartsbevis och pantbrev","Title certificate and mortgage deeds"),"settle",g],["buy",2,"pledge",e("Få pantsättningen registrerad hos föreningen","Have the pledge registered with the association"),e("Bank + förening","Bank + association"),e("Banken meddelar föreningen att bostadsrätten pantsätts och föreningen antecknar det i lägenhetsförteckningen. Kontrollera att säljarens gamla pant avnoteras vid tillträdet. Föreningen får ta ut pantsättningsavgift om stadgarna tillåter det.","The bank notifies the association that the flat is pledged and the association records it in the apartment register. Check that the seller's old pledge is removed at completion. The association may charge a pledge fee if the bylaws allow."),e("Bekräftad pantnotering","Confirmed pledge registration"),"settle",["Andel"]],["buy",2,"insurance",e("Teckna försäkring från tillträdesdagen","Insure the home from completion day"),e("Du + försäkringsbolag","You + insurer"),e("Villa: villahemförsäkring. Bostadsrätt: hemförsäkring med bostadsrättstillägg. Överväg dolda fel-försäkring om säljaren inte erbjuder en. Vid tidigt tillträde: avtala skriftligt vem som bär risken.","House: house-and-home insurance. Bostadsrätt: home insurance with the tenant-owner add-on. Consider hidden-defect insurance if the seller does not offer one. For early access: agree in writing who carries the risk."),e("Försäkringsbrev","Policy document"),"contract"],["buy",2,"handover",e("Genomför tillträdet","Complete the handover"),e("Du + säljare + mäklare","You + seller + agent"),e("Gå igenom bostaden, läs av mätare, ta emot alla nycklar och kontrollera lösöre och utlovade arbeten. Fotografera och anteckna avvikelser. Använd appens tillträdeschecklista.","Walk through the home, read meters, receive all keys and check fixtures and promised work. Photograph and note deviations. Use the app's handover checklist."),e("Tillträdesanteckningar och foton","Handover notes and photos"),"contract"],["buy",3,"claims",e("Reklamera fel inom skälig tid","Complain about defects within reasonable time"),e("Du + säljare","You + seller"),e("Fastighet: dolda fel kan reklameras upp till tio år från tillträdet, men alltid inom skälig tid från upptäckt. Bostadsrätt: köplagen gäller och reklamationstiden är två år. Reklamera skriftligt och dokumentera innan du åtgärdar annat än akut skadebegränsning.","Property: hidden defects can be claimed up to ten years from completion, but always within reasonable time of discovery. Bostadsrätt: the Sale of Goods Act applies and the period is two years. Complain in writing and document before fixing anything beyond urgent damage control."),e("Skriftlig reklamation och svar","Written complaint and reply"),"contract"],["buy",3,"close",e("Få avslutet bekräftat och arkivera","Get closing confirmed and file everything"),e("Bank + du","Bank + you"),e("Kontrollera att lagfart eller medlemskap och pant är registrerade, att slutlikvid och avgifter är betalda och att inga anspråk är öppna. Spara kontrakt, köpebrev, besiktning och budgivningslista. En markering här är din egen anteckning.","Check that title or membership and pledge are registered, that the balance and fees are paid and no claims are open. Keep contract, bill of sale, inspection and bid list. A tick here is your own note."),e("Komplett mapp","Complete file"),"settle"],["sell",0,"proceeds",e("Räkna på nettot efter försäljningen","Work out your net proceeds"),e("Du + bank","You + bank"),e("Räkna fram lösen av lån, mäklararvode, eventuell ränteskillnadsersättning och vinstskatt på 22 % av vinsten. Vinsten deklareras året efter kontraktet; uppskov kan begäras om du köper ny bostad inom reglernas tidsramar.","Calculate loan redemption, agent's fee, any early-repayment charge and capital gains tax of 22% on the gain. The gain is declared the year after contract; deferral can be requested if you buy a new home within the rules' time frames."),e("Nettokalkyl","Net calculation"),"refund"],["sell",0,"agent",e("Välj mäklare och gå igenom förmedlingsuppdraget","Choose an agent and review the brokerage agreement"),e("Du","You"),e("Jämför arvode, ensamrätt, uppdragstid och vad som ingår (foto, styling, annonsering). Det är den enskilda mäklaren, inte firman, som ansvarar för uppdraget. Kontrollera registrering hos Fastighetsmäklarinspektionen.","Compare fee, exclusivity, duration and what is included (photos, styling, advertising). It is the individual agent, not the firm, who is responsible. Check registration with the Estate Agents Inspectorate."),e("Undertecknat förmedlingsuppdrag","Signed brokerage agreement"),"sale"],["sell",0,"docs",e("Samla handlingar och fyll i frågelistan ärligt","Collect documents and fill in the questionnaire honestly"),e("Du + mäklare","You + agent"),e("Ta fram ritningar, bygglov, energideklaration, servicehistorik och kvitton. Svara på mäklarens frågelista efter din faktiska kännedom – du kan hållas ansvarig för felaktiga uppgifter, och en friskrivning gäller inte fel du kände till.","Bring out drawings, building permits, energy declaration, service history and receipts. Answer the agent's questionnaire according to your actual knowledge – you can be held liable for incorrect statements, and a disclaimer does not cover defects you knew of."),e("Dokumentmapp och ifylld frågelista","Document folder and completed questionnaire"),"sale"],["sell",0,"reports",e("Överväg förbesiktning och dolda fel-försäkring","Consider a pre-sale inspection and hidden-defect insurance"),e("Du + mäklare","You + agent"),e("En förbesiktning ger köparen underlag och minskar risken för överraskningar, men tar inte bort köparens undersökningsplikt. Du svarar för dolda fel i tio år; en säljarförsäkring kan täcka delar av det. Jämför villkor.","A pre-sale inspection gives the buyer information and reduces surprises, but does not remove the buyer's duty to inspect. You are liable for hidden defects for ten years; seller's insurance can cover part of that. Compare terms."),e("Besiktningsprotokoll och försäkringsofferter","Inspection protocol and insurance quotes"),"sale",g],["sell",0,"association",e("Hämta underlag från föreningen","Get documents from the association"),e("Du + styrelse","You + board"),e("Mäklaren behöver årsredovisning, stadgar, utdrag ur lägenhetsförteckningen och uppgift om avgift och planerade arbeten. Ta reda på om föreningen tar ut överlåtelseavgift och vem som betalar enligt stadgarna.","The agent needs the annual report, bylaws, extract from the apartment register and details of fees and planned work. Find out whether the association charges a transfer fee and who pays under the bylaws."),e("Föreningens handlingar","Association documents"),"sale",["Andel"]],["sell",0,"market",e("Gör bostaden och annonsen klar","Prepare the home and the listing"),e("Du + mäklare","You + agent"),e("Godkänn objektsbeskrivning, foton och utgångspris. Kontrollera att alla uppgifter stämmer – du svarar för felaktiga uppgifter i marknadsföringen. Bestäm hur budgivningen ska gå till och informera spekulanter i förväg.","Approve the description, photos and asking price. Check that every detail is correct – you are liable for incorrect marketing information. Decide how bidding will run and inform prospective buyers in advance."),e("Godkänt säljmaterial","Approved sales material"),"sale"],["sell",1,"negotiate",e("Bedöm buden samlat","Assess the bids as a whole"),e("Du + mäklare","You + agent"),e("Du väljer fritt köpare, pris och tidpunkt – högsta budet måste inte vinna. Jämför pris, tillträdesdag, villkor som besiktningsklausul och lånevillkor, och köparens finansiering. Inga bud är bindande före kontraktet.","You freely choose buyer, price and timing – the highest bid need not win. Compare price, completion date, conditions such as inspection clauses and financing, and the buyer's funding. No bid is binding before contract."),e("Accepterade villkor","Accepted terms"),"approval"],["sell",1,"contract",e("Gå igenom och skriv under köpekontraktet","Review and sign the purchase contract"),e("Du + mäklare","You + agent"),e("Kontrollera pris, handpenning, tillträde, lösöre, villkor och friskrivningar. Är du gift eller sambo krävs normalt makens/sambons samtycke. Efter underskrift kan du inte ångra dig utan att bryta avtalet.","Check price, deposit, completion, fixtures, conditions and disclaimers. If married or cohabiting, your partner's consent is normally required. After signing you cannot withdraw without breaching the contract."),e("Undertecknat kontrakt","Signed contract"),"contract"],["sell",1,"conditions",e("Följ köparens villkor och frister","Follow the buyer's conditions and deadlines"),e("Mäklare + du","Agent + you"),e("Bevaka besiktningsklausul, lånevillkor och – för bostadsrätt – köparens medlemskap. Be mäklaren bekräfta skriftligt när alla villkor är uppfyllda innan du räknar affären som klar.","Monitor the inspection clause, financing condition and – for a bostadsrätt – the buyer's membership. Ask the agent to confirm in writing when all conditions are met before treating the deal as done."),e("Skriftlig status från mäklaren","Written status from the agent"),"approval"],["sell",2,"works",e("Slutför avtalade arbeten och lösörelistan","Finish agreed work and the fixtures list"),e("Du","You"),e("Gör det du lovat och spara dokumentation. Klargör skriftligt vad som stannar och vad du tar med. Boka flyttstädning – den ger rutavdrag.","Do what you promised and keep documentation. Clarify in writing what stays and what you take. Book move-out cleaning – it qualifies for RUT deduction."),e("Foton, kvitton och lista","Photos, receipts and list"),"contract"],["sell",2,"bank",e("Samordna lösen av lån och slutlikvid","Coordinate loan redemption and final payment"),e("Bank + mäklare","Bank + agent"),e("Banken tar fram lösenbesked och pantbrev. På tillträdet betalas slutlikviden, lånen löses och köpebrev skrivs. Fråga när överskottet finns på ditt konto.","The bank prepares the redemption statement and mortgage deeds. At completion the balance is paid, loans redeemed and the bill of sale signed. Ask when the surplus will be in your account."),e("Lösenbesked och bankens bekräftelse","Redemption statement and bank confirmation"),"settle"],["sell",2,"handover",e("Lämna över bostaden som avtalat","Hand over the home as agreed"),e("Du + köpare + mäklare","You + buyer + agent"),e("Genomgång, mätaravläsning, alla nycklar, manualer och garantier. Bostaden ska vara tömd och städad enligt kontraktet vid den avtalade tiden.","Walk-through, meter readings, all keys, manuals and warranties. The home must be emptied and cleaned per the contract at the agreed time."),e("Tillträdesanteckningar","Handover notes"),"contract"],["sell",3,"tax",e("Förbered deklarationen av försäljningen","Prepare the tax return for the sale"),e("Du","You"),e("Räkna fram vinst eller förlust redan nu i Skatteverkets e-tjänst och spara underlag för förbättringsutgifter. Begär uppskov på K5/K6 om du köpt ersättningsbostad – uppskovsbeloppet ska vara minst 50 000 kr.","Calculate gain or loss now in Skatteverket's e-service and keep records of improvement costs. Request deferral on K5/K6 if you bought a replacement home – the deferred amount must be at least 50,000 SEK."),e("Beräkning och underlag","Calculation and records"),"refund"],["sell",3,"close",e("Avsluta öppna frågor och spara mappen","Close open questions and keep the file"),e("Du + mäklare","You + agent"),e("Få budgivningslista och journal från mäklaren. Spara kontrakt, köpebrev, frågelista och foton i minst tio år – så länge kan köparen reklamera dolda fel i en fastighet.","Get the bid list and journal from the agent. Keep contract, bill of sale, questionnaire and photos for at least ten years – that is how long a buyer can claim hidden defects in a property."),e("Komplett mapp","Complete file"),"settle"],["rentIn",0,"budget",e("Räkna på hyra, el och dubbla kostnader","Budget rent, electricity and overlapping costs"),e("Du","You"),e("Hyra betalas i förskott per månad. Ta reda på om el, värme, vatten och bredband ingår. Räkna med eventuell deposition vid andrahand och en period med dubbla boendekostnader. Kontrollera om du kan få bostadsbidrag.","Rent is paid monthly in advance. Find out whether electricity, heating, water and broadband are included. Allow for a deposit if subletting and a period of double housing costs. Check whether you qualify for housing allowance."),e("Inflyttningsbudget","Move-in budget"),"rent"],["rentIn",0,"verify",e("Kontrollera hyresvärd och avtalsform","Check the landlord and contract type"),e("Du","You"),e("Är det förstahand, andrahand eller inneboende? Vid andrahand: be att få se hyresvärdens eller föreningens tillstånd. Hyran i andra hand får inte överstiga förstahandshyran med mer än kostnad för möbler. Betala aldrig innan du sett lägenheten och avtalet.","Is it first-hand, sublet or lodging? For a sublet: ask to see the landlord's or association's permission. A sublet rent may not exceed the first-hand rent by more than the cost of furnishings. Never pay before seeing the flat and the contract."),e("Verifierad motpart och tillstånd","Verified counterparty and permission"),"rent"],["rentIn",1,"contract",e("Gå igenom hyresavtalet","Review the tenancy agreement"),e("Du + hyresrådgivare","You + tenant adviser"),e("Du har rätt till skriftligt avtal. Kontrollera hyra, vad som ingår, hyrestid, uppsägningstid (normalt tre månader) och eventuella särskilda villkor. Hyresgästföreningen ger medlemmar rådgivning.","You are entitled to a written contract. Check rent, what is included, term, notice period (normally three months) and any special terms. The Tenants' Association advises members."),e("Genomgånget avtal","Reviewed contract"),"rent"],["rentIn",1,"payment",e("Avtala och dokumentera första betalningen","Agree and document the first payment"),e("Du + hyresvärd","You + landlord"),e("Bekräfta belopp, mottagare och förfallodag. Du måste betala hyran i tid även om hyresavin inte kommit. Spara avtal och kvitton.","Confirm amount, recipient and due date. You must pay rent on time even if the invoice has not arrived. Keep contract and receipts."),e("Betalningskvitto","Payment receipt"),"rent"],["rentIn",2,"inspection",e("Besiktiga lägenheten vid inflyttning","Inspect the flat at move-in"),e("Du + hyresvärd","You + landlord"),e("Be om kopia av protokollet från förra hyresgästens avflyttningsbesiktning och begär gärna gemensam genomgång. Fotografera eller filma allt, läs av mätare och räkna nycklar. Tillträde är normalt kl. 12 första dagen.","Ask for a copy of the protocol from the previous tenant's move-out inspection and request a joint walk-through. Photograph or film everything, read meters and count keys. Access is normally at noon on the first day."),e("Protokoll och daterade foton","Protocol and dated photos"),"rentIn"],["rentIn",2,"defects",e("Anmäl brister skriftligt till hyresvärden","Report defects in writing to the landlord"),e("Du","You"),e("Skador som inte står i protokollet ska du anmäla skriftligt direkt, så att du inte får betala för dem vid avflyttning. Ingen lag kräver besiktning – din skriftliga lista är ditt bevis. Spara kopia.","Report in writing immediately any damage not in the protocol, so you do not pay for it when you leave. No law requires an inspection – your written list is your evidence. Keep a copy."),e("Skickad lista och kvittens","Sent list and acknowledgement"),"rentIn"],["rentIn",3,"follow",e("Följ upp felanmälan och första hyresavin","Follow up on repairs and the first rent invoice"),e("Du + hyresvärd","You + landlord"),e("Följ avtalade åtgärder och kontrollera att första avin stämmer. Spara dokumentationen – du behöver den vid avflyttning.","Follow agreed repairs and check that the first invoice is correct. Keep the documentation – you will need it when you move out."),e("Avklarade punkter","Resolved items"),"rentIn"],["rentOut",0,"notice",e("Kontrollera uppsägningstid och sista hyresdag","Check the notice period and last rent day"),e("Du","You"),e("Normalt tre hela kalendermånader från månadsskiftet efter uppsägningen. Vid tidsbestämda avtal kan andra regler gälla. Flyttar du tidigare betalar du ändå hyran ut, om inte hyresvärden går med på annat.","Normally three full calendar months from the month-end after notice. Fixed-term contracts may differ. If you leave earlier you still pay rent to the end unless the landlord agrees otherwise."),e("Bekräftade datum","Confirmed dates"),"rentOut"],["rentOut",1,"terminate",e("Säg upp skriftligt och spara bekräftelsen","Give written notice and keep the confirmation"),e("Du + hyresvärd","You + landlord"),e("Skicka uppsägningen skriftligt, gärna rekommenderat eller via hyresvärdens e-tjänst, och be om bekräftelse med avtalets slutdatum. Uppge din nya adress för slutavräkning.","Send notice in writing, preferably registered or via the landlord's e-service, and ask for confirmation with the end date. Give your new address for the final settlement."),e("Uppsägning och bekräftelse","Notice and confirmation"),"rentOut"],["rentOut",2,"prepare",e("Förbered besiktning och städning","Prepare the inspection and cleaning"),e("Du","You"),e("Ta fram inflyttningsprotokoll och foton. Du betalar inte för normalt slitage men för skador du, din familj eller gäster orsakat. Under sista månaden får hyresvärden inte måla om utan ditt tillstånd. Boka flyttstädning (rutavdrag).","Bring out the move-in protocol and photos. You do not pay for normal wear but for damage caused by you, your family or guests. In the final month the landlord may not repaint without your permission. Book move-out cleaning (RUT deduction)."),e("Besiktningstid och dokumentation","Inspection time and documentation"),"rentOut"],["rentOut",2,"inspection",e("Delta i avflyttningsbesiktningen och lämna nycklar","Attend the move-out inspection and hand in keys"),e("Du + hyresvärd","You + landlord"),e("Var med vid besiktningen, be om kopia av protokollet och anteckna om du inte håller med. Lämna alla nycklar inklusive tvättstuga och förråd mot kvitto. Hyresvärden måste bevisa att skador uppstått under din tid.","Attend the inspection, ask for a copy of the protocol and note any disagreement. Hand in all keys including laundry and storage against a receipt. The landlord must prove damage occurred during your tenancy."),e("Protokoll och nyckelkvitto","Protocol and key receipt"),"rentOut"],["rentOut",3,"deposit",e("Följ upp slutavräkning, deposition och krav","Follow up on final settlement, deposit and claims"),e("Du + hyresvärd","You + landlord"),e("Jämför eventuella krav med protokoll och foton. Hyresvärden kan ställa krav upp till två år efter avflyttning. Är ni oense: kontakta Hyresgästföreningen eller låt hyresnämnden medla.","Compare any claims with protocols and photos. The landlord can make claims up to two years after you leave. In a dispute: contact the Tenants' Association or let the rent tribunal mediate."),e("Avräkning och dokumentation","Settlement and documentation"),"rentOut"]],ee="2026-10-19",a={before:e("Före kontrakt","Before contract"),during:e("Under affären","During the deal"),access:e("Före tillträde","Before completion"),after:e("Efter tillträde","After completion")},n=(d,h,D,F,C,x,I,R,H,V,G,P)=>({id:d,tracks:h.split(","),phase:D,title:F,term:C,definition:x,answer:I,who:R,when:H,action:V,ask:G,url:P}),te=[n("bud","buy,sell",a.before,e("Är mitt bud bindande?","Is my bid binding?"),e("Budgivning","Bidding"),e("Säljarens sätt att ta in anbud via mäklaren.","The seller's way of collecting offers via the agent."),e("Nej. Ett bud är inte bindande för någon part förrän köpekontraktet är undertecknat av både köpare och säljare. Säljaren väljer fritt vem som får köpa och till vilket pris – högsta budet måste inte vinna. Mäklaren ska föra vidare alla bud och lämna budgivningslistan till båda parter efter affären.","No. A bid is not binding on anyone until the purchase contract is signed by both buyer and seller. The seller freely chooses who buys and at what price – the highest bid need not win. The agent must relay all bids and hand the bid list to both parties after the deal."),e("Köpare, säljare och mäklare","Buyer, seller and agent"),e("Under hela budgivningen fram till kontrakt.","Throughout bidding until contract."),e("Bestäm din maxgräns och be om budgivningslistan","Set your maximum and ask for the bid list"),e("Hur vill säljaren genomföra budgivningen, och finns det villkor i andra bud?","How does the seller want to run the bidding, and do other bids carry conditions?"),T),n("undersokningsplikt","buy",a.before,e("Vad innebär undersökningsplikten?","What does the duty to inspect mean?"),e("Undersökningsplikt","Duty to inspect"),e("Köparens skyldighet att noggrant undersöka bostaden före köpet.","The buyer's obligation to examine the home carefully before purchase."),e("För fastighet gäller jordabalken: fel du borde ha upptäckt vid en noggrann undersökning kan du inte kräva ersättning för. Plikten omfattar hela fastigheten – även el, VVS, eldstad, tomt och radon, som en vanlig överlåtelsebesiktning ofta inte täcker. Hittar du tecken på fel utökas plikten. För bostadsrätt finns ingen lagstadgad plikt, men uppmanar säljaren dig att undersöka kan du förlora rätten till ersättning om du låter bli.","For a property the Land Code applies: you cannot claim for defects you should have found in a careful examination. The duty covers the whole property – including electrics, plumbing, fireplace, plot and radon, which a standard transfer inspection often excludes. Signs of defects extend the duty. For a bostadsrätt there is no statutory duty, but if the seller urges you to inspect you may lose compensation rights if you do not."),e("Köpare, gärna med besiktningsman","Buyer, preferably with an inspector"),e("Före kontrakt, eller inom besiktningsklausulens frist.","Before contract, or within the inspection clause deadline."),e("Beställ besiktning och tilläggskontroller","Order an inspection and extra checks"),e("Vad ingår inte i besiktningen, och vilka fynd kräver vidare undersökning?","What is excluded from the inspection, and which findings need further investigation?"),v),n("besiktningsklausul","buy,sell",a.during,e("Kan jag besiktiga efter att kontraktet är skrivet?","Can I inspect after the contract is signed?"),e("Besiktningsklausul","Inspection clause"),e("Ett villkor i kontraktet som låter köparen frånträda köpet efter besiktning.","A contract condition letting the buyer withdraw after an inspection."),e("Bara om kontraktet innehåller en besiktningsklausul. Klausulen bör vara så vid att du kan frånträda utan att ange särskilda skäl, och den har en exakt frist och ett sätt att meddela. Missar du fristen blir köpet bindande utan villkor. Mäklaren ska föreslå en klausul om besiktning inte hinns med före kontraktet.","Only if the contract contains an inspection clause. It should be wide enough that you can withdraw without specific reasons, and it has an exact deadline and notification method. Miss the deadline and the purchase becomes unconditional. The agent should propose a clause if inspection cannot happen before contract."),e("Köpare, säljare och mäklare","Buyer, seller and agent"),e("Skrivs in vid kontraktet; följ fristen exakt.","Written into the contract; follow the deadline exactly."),e("Få klausulens ordalydelse, frist och mottagare bekräftade","Get the clause wording, deadline and recipient confirmed"),e("Kan jag frånträda utan skäl, och till vem och när ska beskedet lämnas?","Can I withdraw without reasons, and to whom and when must notice be given?"),S),n("kontrakt","buy,sell",a.before,e("Vad måste stå i köpekontraktet?","What must the purchase contract contain?"),e("Köpekontrakt","Purchase contract"),e("Det skriftliga avtalet som gör affären bindande.","The written agreement that makes the deal binding."),e("Köp av fastighet kräver skriftligt kontrakt med fastighetsbeteckning, parter, pris och en överlåtelseförklaring; säljarens underskrift bör bevittnas av två personer för full lagfart. För bostadsrätt ska kontraktet ange lägenheten, priset och datum. Avtal om annat pris vid sidan av är ogiltiga. Läs den slutliga versionen med bilagor – inte bara utkastet.","A property purchase needs a written contract with property designation, parties, price and a transfer declaration; the seller's signature should be witnessed by two people for full title. For a bostadsrätt the contract must state the flat, price and date. Side agreements on a different price are invalid. Read the final version with annexes – not just the draft."),e("Köpare, säljare och mäklare","Buyer, seller and agent"),e("Före underskrift.","Before signing."),e("Gå igenom kontraktets villkor, bilagor och friskrivningar","Review the contract's conditions, annexes and disclaimers"),e("Är alla löften om lösöre, arbeten och datum inskrivna?","Are all promises about fixtures, work and dates written in?"),r),n("handpenning","buy,sell",a.during,e("Hur fungerar handpenningen?","How does the deposit work?"),e("Handpenning","Deposit"),e("Köparens delbetalning strax efter kontraktet som säkerhet för affären.","The buyer's part-payment shortly after contract as security for the deal."),e("Belopp och betalningsdag står i kontraktet; mäklaren ska verka för en tillräckligt stor handpenning. Den betalas ofta till mäklarens klientmedelskonto och redovisas till säljaren när villkoren är uppfyllda. Frånträder köparen utan rätt enligt villkoren kan handpenningen gå förlorad. Bekräfta kontonumret via en känd kanal innan du betalar.","Amount and payment date are in the contract; the agent must work towards an adequate deposit. It is often paid into the agent's client account and released to the seller once conditions are met. If the buyer withdraws without a right under the conditions, the deposit may be forfeited. Confirm the account number through a known channel before paying."),e("Köpare, mäklare och bank","Buyer, agent and bank"),e("Inom den frist kontraktet anger, ofta några dagar.","Within the deadline in the contract, often a few days."),e("Bekräfta belopp, datum och klientmedelskonto","Confirm amount, date and client account"),e("När redovisas handpenningen till säljaren, och vad händer vid frånträde?","When is the deposit released to the seller, and what happens on withdrawal?"),r),n("maklare","buy,sell",a.before,e("Är mäklaren min rådgivare?","Is the agent my adviser?"),e("Fastighetsmäklare","Estate agent"),e("En registrerad, opartisk mellanman som anlitas av en av parterna.","A registered, impartial intermediary hired by one of the parties."),e("Mäklaren ska ta hänsyn till både köpare och säljare men verka för uppdragsgivarens pris. Mäklaren ska informera om undersökningsplikten, erbjuda boendekostnadskalkyl, föra budgivningslista och hjälpa till med handlingar vid kontrakt och tillträde. Mäklaren besiktigar inte bostaden. Vill du ha någon som bara bevakar dina intressen, anlita egen jurist eller besiktningsman.","The agent must consider both buyer and seller but work for the client's price. The agent must inform about the duty to inspect, offer a housing-cost calculation, keep a bid list and help with documents at contract and completion. The agent does not inspect the home. If you want someone looking only after your interests, hire your own lawyer or inspector."),e("Köpare och säljare","Buyer and seller"),e("Innan du förlitar dig på mäklarens råd.","Before relying on the agent's advice."),e("Be om boendekalkyl och skriftlig information om undersökningsplikten","Ask for a housing-cost calculation and written information on the duty to inspect"),e("Vilka uppgifter har du kontrollerat, och vad bör jag undersöka själv?","What have you verified, and what should I check myself?"),B),n("lagfart","buy",a.after,e("Vad kostar lagfart och pantbrev?","What do title registration and mortgage deeds cost?"),e("Lagfart och stämpelskatt","Title registration and stamp duty"),e("Registrering av dig som ägare hos Lantmäteriet, och skatten på köpet.","Registration of you as owner with Lantmäteriet, and the tax on the purchase."),e("Lagfart ska sökas inom tre månader från köpet. Stämpelskatten är 1,5 % för privatpersoner, beräknad på det högsta av köpeskillingen och föregående års taxeringsvärde, plus expeditionsavgift 825 kr. Nya pantbrev kostar 2 % av inteckningsbeloppet plus 375 kr per pantbrev. Befintliga pantbrev följer fastigheten och kan återanvändas. Banken sköter oftast ansökan.","Title must be applied for within three months of purchase. Stamp duty is 1.5% for private individuals, calculated on the higher of the price and last year's assessed value, plus an 825 SEK fee. New mortgage deeds cost 2% of the amount plus 375 SEK each. Existing deeds follow the property and can be reused. The bank usually handles the application."),e("Köpare och bank","Buyer and bank"),e("Inom tre månader efter köpet.","Within three months of purchase."),e("Räkna in lagfart och pantbrev i kontantinsatsen","Include title and mortgage deed costs in your cash deposit"),e("Finns befintliga pantbrev, och hur stort belopp behöver vi i nya?","Are there existing mortgage deeds, and how much do we need in new ones?"),Y),n("dolda-fel","buy,sell",a.after,e("Vad är ett dolt fel och hur länge gäller ansvaret?","What is a hidden defect and how long does liability last?"),e("Dolt fel","Hidden defect"),e("Ett fel som fanns vid köpet men inte kunde upptäckas trots noggrann undersökning.","A defect present at purchase that could not be found despite careful inspection."),e("För fastighet kan köparen reklamera dolda fel upp till tio år från tillträdet, men alltid inom skälig tid efter upptäckt. Felet ska vara oväntat med hänsyn till ålder, skick och byggsätt. Säljaren kan inte friskriva sig från fel hen kände till. För bostadsrätt gäller köplagen och reklamationstiden är två år. Reklamera skriftligt och spara beviset.","For a property the buyer can claim hidden defects up to ten years from completion, but always within reasonable time of discovery. The defect must be unexpected given age, condition and construction. A seller cannot disclaim defects they knew of. For a bostadsrätt the Sale of Goods Act applies and the period is two years. Complain in writing and keep proof."),e("Köpare och säljare; jurist vid tvist","Buyer and seller; lawyer in disputes"),e("Så snart felet upptäcks.","As soon as the defect is discovered."),e("Dokumentera felet och reklamera skriftligt till säljaren","Document the defect and complain in writing to the seller"),e("Täcker min hemförsäkrings rättsskydd en tvist, och finns dolda fel-försäkring?","Does my home insurance legal cover apply, and is there hidden-defect insurance?"),A),n("fragelista","sell",a.before,e("Vad måste jag berätta som säljare?","What must I disclose as a seller?"),e("Säljarens upplysningar","Seller's disclosures"),e("Det säljaren uppger om bostadens skick i frågelistan och objektsbeskrivningen.","What the seller states about the home's condition in the questionnaire and description."),e("Det finns ingen generell upplysningsplikt, men felaktiga uppgifter kan ge prisavdrag eller hävning, och en friskrivning gäller inte fel du kände till. Mäklarens frågelista blir en del av underlaget – svara efter din faktiska kännedom och skilj på det du vet och det du gissar. Uppgifter du lämnar kan både minska och utöka köparens undersökningsplikt.","There is no general duty to disclose, but incorrect statements can lead to price reduction or rescission, and a disclaimer does not cover defects you knew about. The agent's questionnaire becomes part of the record – answer according to actual knowledge and separate what you know from what you guess. Your statements can both reduce and extend the buyer's duty to inspect."),e("Säljare och mäklare","Seller and agent"),e("Innan annonsering och kontrakt.","Before listing and contract."),e("Fyll i frågelistan noggrant och samla dokumentation","Complete the questionnaire carefully and gather documentation"),e("Vilka kända fel, skador och renoveringar ska jag redovisa?","Which known defects, damage and renovations should I report?"),v),n("medlemskap","buy,sell",a.during,e("Kan föreningen neka mig medlemskap?","Can the association refuse me membership?"),e("Medlemskapsprövning","Membership review"),e("Styrelsens beslut om att godkänna köparen som medlem i bostadsrättsföreningen.","The board's decision to accept the buyer as a member of the housing association."),e("Köpet av en bostadsrätt fullbordas först när styrelsen beviljat medlemskap. Styrelsen får bara neka undantagsvis, t.ex. vid stora obetalda boendeskulder eller ålderskrav i seniorförening; krav på inkomst eller förmögenhet och diskriminerande skäl är inte tillåtna. Ett avslag kan prövas av hyresnämnden. Skicka ansökan direkt efter kontraktet så att beslutet hinner före tillträdet.","A bostadsrätt purchase is completed only when the board grants membership. The board may refuse only exceptionally, e.g. large unpaid housing debts or age rules in a senior association; income or wealth requirements and discriminatory grounds are not allowed. A refusal can be reviewed by the rent tribunal. Send the application right after contract so the decision arrives before completion."),e("Köpare, säljare och styrelsen","Buyer, seller and the board"),e("Direkt efter kontraktet.","Right after contract."),e("Skicka medlemskapsansökan och följ upp beslutet","Send the membership application and follow up the decision"),e("Hur lång handläggningstid har styrelsen, och vad kräver stadgarna?","How long does the board take, and what do the bylaws require?"),K),n("brf-ekonomi","buy",a.before,e("Hur granskar jag bostadsrättsföreningen?","How do I review the housing association?"),e("Årsredovisning","Annual report"),e("Föreningens räkenskaper, som styr din månadsavgift framöver.","The association's accounts, which drive your future monthly fee."),e("Läs skuldsättning, avsättning till underhåll, planerade arbeten (stambyte, tak, fasad) och om styrelsen beviljats ansvarsfrihet. Låg avgift kan betyda eftersatt underhåll. Läs stadgarna om vem som ansvarar för fönster, dörrar och ytskikt. Be om utdrag ur lägenhetsförteckningen för att se om lägenheten är pantsatt – panten följer lägenheten, inte säljaren.","Read debt, maintenance reserves, planned work (pipes, roof, facade) and whether the board was discharged. A low fee can mean neglected maintenance. Read the bylaws on who is responsible for windows, doors and surfaces. Ask for an extract from the apartment register to see if the flat is pledged – the pledge follows the flat, not the seller."),e("Köpare, bank och styrelsen","Buyer, bank and the board"),e("Före bud och kontrakt.","Before bidding and contract."),e("Läs årsredovisning, stadgar och lägenhetsförteckning","Read the annual report, bylaws and apartment register"),e("Vilka större arbeten är planerade, och hur påverkar de avgiften?","What major work is planned, and how will it affect the fee?"),L),n("tilltrade","buy,sell",a.access,e("Vad händer på tillträdesdagen?","What happens on completion day?"),e("Tillträde","Completion"),e("Dagen då bostaden, nycklarna och betalningen byter händer.","The day the home, keys and payment change hands."),e("Oftast på banken eller hos mäklaren: köparens bank betalar slutlikviden, säljarens lån löses, köpebrev skrivs och nycklarna lämnas över. Gå igenom bostaden, läs av mätare och kontrollera lösöre och lovade arbeten. Vill ni ha tillträde tidigare ska mäklaren dokumentera ett särskilt avtal om risk och villkor.","Usually at the bank or the agent's office: the buyer's bank pays the balance, the seller's loans are redeemed, the bill of sale is signed and keys are handed over. Walk through the home, read meters and check fixtures and promised work. For early access the agent must document a special agreement on risk and conditions."),e("Köpare, säljare, mäklare och banker","Buyer, seller, agent and banks"),e("Den dag som står i kontraktet.","The date in the contract."),e("Bekräfta tid, plats, handlingar och mätaravläsning","Confirm time, place, documents and meter readings"),e("Vem rapporterar mätarställningar, och när är bostaden tömd och städad?","Who reports the meter readings, and when is the home emptied and cleaned?"),r),n("vinstskatt","sell",a.after,e("Hur beskattas vinsten och kan jag skjuta upp skatten?","How is the gain taxed and can I defer it?"),e("Vinstskatt och uppskov","Capital gains tax and deferral"),e("Skatten på vinsten vid bostadsförsäljning och möjligheten att skjuta upp den.","The tax on the gain from a home sale and the option to defer it."),e("Vinsten beskattas i praktiken med 22 %; en förlust får dras av till hälften. Försäljningen deklareras året efter att kontraktet skrevs, oavsett tillträde. Köper du en ersättningsbostad inom reglernas tidsramar kan du begära uppskov på K5 (hus) eller K6 (bostadsrätt); beloppet ska vara minst 50 000 kr och högst 3 000 000 kr.","The gain is effectively taxed at 22%; half of a loss is deductible. The sale is declared the year after the contract was signed, regardless of completion. If you buy a replacement home within the rules' time frames you can request deferral on form K5 (house) or K6 (bostadsrätt); the amount must be between 50,000 and 3,000,000 SEK."),e("Säljare","Seller"),e("I deklarationen året efter kontraktet.","In the tax return the year after contract."),e("Räkna fram vinsten i Skatteverkets e-tjänst och spara underlag","Calculate the gain in Skatteverket's e-service and keep records"),e("Vilka förbättringsutgifter får jag dra av, och lönar sig uppskov för mig?","Which improvement costs can I deduct, and is deferral worthwhile for me?"),E),n("uppsagning","rentOut",a.before,e("Hur lång är uppsägningstiden för min hyresrätt?","How long is the notice period for my rental?"),e("Uppsägningstid","Notice period"),e("Tiden från uppsägning till att hyresavtalet upphör.","The time from notice until the tenancy ends."),e("Vanligtvis tre hela kalendermånader: säger du upp den 8 september räknas oktober, november och december, och avtalet gäller till 31 december. Månaden du säger upp i räknas inte. En kortare avtalad tid gäller bara till din fördel. Säg upp skriftligt och be om bekräftelse. Flyttar du tidigare betalar du ändå hyran ut.","Usually three full calendar months: give notice on 8 September and October, November and December count, so the contract runs to 31 December. The month you give notice in does not count. A shorter agreed period only applies in your favour. Give notice in writing and ask for confirmation. If you leave earlier you still pay rent to the end."),e("Hyresgäst och hyresvärd","Tenant and landlord"),e("Innan du bestämmer flyttdatum.","Before setting your moving date."),e("Säg upp skriftligt och få slutdatum bekräftat","Give written notice and get the end date confirmed"),e("Kan hyresvärden hyra ut tidigare så att jag slipper dubbel hyra?","Can the landlord re-let earlier so I avoid double rent?"),k),n("deposition","rentIn,rentOut",a.before,e("Måste jag betala deposition?","Do I have to pay a deposit?"),e("Deposition","Deposit"),e("Ett belopp som säkerhet för hyresvärdens krav vid avflyttning.","A sum held as security for the landlord's claims at move-out."),e("Deposition är ovanligt vid förstahandskontrakt hos större hyresvärdar men förekommer vid andrahand och privat uthyrning. Det finns inget lagstadgat tak; avtala beloppet skriftligt och när det återbetalas. Hyresvärden får bara dra av för skador som kan bevisas – inte normalt slitage. Betala aldrig deposition innan du sett lägenheten och avtalet.","Deposits are uncommon for first-hand tenancies with larger landlords but occur with sublets and private landlords. There is no statutory cap; agree the amount in writing and when it is returned. The landlord may only deduct for provable damage – not normal wear. Never pay a deposit before seeing the flat and the contract."),e("Hyresgäst och hyresvärd","Tenant and landlord"),e("Innan avtal och betalning; igen vid avflyttning.","Before contract and payment; again at move-out."),e("Avtala depositionens belopp och återbetalning skriftligt","Agree the deposit amount and refund in writing"),e("Vad får dras av, och när betalas depositionen tillbaka?","What may be deducted, and when is the deposit refunded?"),m),n("besiktning-hyra","rentIn,rentOut",a.access,e("Hur fungerar besiktning av en hyresrätt?","How does the inspection of a rental work?"),e("Lägenhetsbesiktning","Flat inspection"),e("Hyresvärdens genomgång av lägenhetens skick vid in- och avflyttning.","The landlord's review of the flat's condition at move-in and move-out."),e("Ingen lag kräver besiktning, men hyresvärden bör göra en vid avflyttning och anteckna skador i ett protokoll. Vid inflyttning: be om kopia av förra hyresgästens protokoll och anmäl skriftligt skador som saknas. Du betalar inte för normalt slitage; hyresvärden måste bevisa att skadan uppstått under din tid, och utan protokoll är det svårt. Krav kan ställas upp till två år efter avflyttning.","No law requires an inspection, but the landlord should do one at move-out and record damage in a protocol. At move-in: ask for a copy of the previous tenant's protocol and report missing damage in writing. You do not pay for normal wear; the landlord must prove damage occurred during your tenancy, and without a protocol that is hard. Claims can be made up to two years after move-out."),e("Hyresgäst och hyresvärd","Tenant and landlord"),e("Vid in- och avflyttning.","At move-in and move-out."),e("Fotografera och be om kopia av protokollet","Photograph and ask for a copy of the protocol"),e("Får jag vara med vid besiktningen, och vad räknas som normalt slitage?","May I attend the inspection, and what counts as normal wear?"),u),n("flyttanmalan","common",a.after,e("När ska jag göra flyttanmälan?","When should I report my move?"),e("Flyttanmälan","Move report"),e("Anmälan av din nya folkbokföringsadress till Skatteverket.","Reporting your new registered address to Skatteverket."),e("Gör anmälan gratis i Skatteverkets e-tjänst före flytten eller senast en vecka efter inflyttningen – då gäller adressen från inflyttningsdagen. Anmäler du senare gäller den från den dag anmälan kommer in. Flyttar barn ska båda vårdnadshavarna godkänna. Flyttanmälan flyttar inte din post; eftersändning beställs separat mot avgift hos Svensk Adressändring.","Report for free in Skatteverket's e-service before the move or at the latest one week after moving in – then the address applies from the move-in date. Report later and it applies from the day the report arrives. If children move, both guardians must approve. The move report does not forward mail; forwarding is ordered separately for a fee from Svensk Adressändring."),e("Du och Skatteverket","You and Skatteverket"),e("Senast en vecka efter inflyttning.","At the latest one week after moving in."),e("Gör flyttanmälan med e-legitimation","Report the move with e-ID"),e("Vilken dag flyttar jag faktiskt in, och behöver barnens andra vårdnadshavare samtycka?","Which day do I actually move in, and does the children's other guardian need to consent?"),i),n("elavtal","common",a.access,e("Vilka elavtal behöver jag när jag flyttar?","Which electricity contracts do I need when moving?"),e("Elnäts- och elhandelsavtal","Grid and supply contracts"),e("De två avtal som krävs för att ha el i bostaden.","The two contracts required to have electricity in the home."),e("Du behöver både ett elnätsavtal med det lokala nätföretaget (kan inte väljas) och ett elhandelsavtal med valfri elhandlare. Vid flytt måste båda avslutas på gamla adressen – ofta minst en månad respektive 14 dagar i förväg – och tecknas på den nya. Betalningsansvaret kvarstår tills avtalen är avslutade. Väljer du ingen elhandlare får du ett anvisat avtal, som ofta är dyrare.","You need both a grid contract with the local grid company (cannot be chosen) and a supply contract with any supplier. When moving, both must be ended at the old address – often at least one month and 14 days in advance respectively – and signed at the new one. You remain liable until the contracts are ended. If you choose no supplier you get an assigned contract, often more expensive."),e("Du, elnätsföretaget och elhandlaren","You, the grid company and the supplier"),e("Minst en månad före flytten.","At least one month before the move."),e("Säg upp och teckna båda avtalen med rätt datum","End and sign both contracts with the right dates"),e("Kan mitt bundna elhandelsavtal flyttas med, och tar nätföretaget ut flyttavgift?","Can my fixed supply contract move with me, and does the grid company charge a moving fee?"),o),n("hemforsakring","common",a.access,e("Gäller hemförsäkringen under flytten?","Does home insurance apply during the move?"),e("Flyttskydd","Moving cover"),e("Hemförsäkringens skydd när du har två bostäder samtidigt.","The home policy's cover when you have two homes at once."),e("Många hemförsäkringar täcker både gamla och nya adressen i 14–45 dagar och ibland sakerna under transport, men villkoren skiljer sig. Meddela bolaget flyttdatum så att skyddet gäller från inflyttningen. Bostadsrätt kräver bostadsrättstillägg och villa en villahemförsäkring. Kontrollera att flyttfirman har ansvarsförsäkring och yrkestrafiktillstånd.","Many home policies cover both the old and new address for 14–45 days and sometimes belongings in transit, but terms vary. Tell the insurer your moving date so cover applies from move-in. A bostadsrätt needs the tenant-owner add-on and a house needs house-and-home insurance. Check that the moving company has liability insurance and a transport licence."),e("Du och försäkringsbolaget","You and the insurer"),e("Innan flyttdagen.","Before moving day."),e("Bekräfta skriftligt vilka adresser och datum som täcks","Confirm in writing which addresses and dates are covered"),e("Täcks sakerna under transport, och hur länge gäller skyddet för båda bostäderna?","Are belongings covered in transit, and how long are both homes covered?"),s),n("flyttfirma","common",a.access,e("Vad ska jag kräva av flyttfirman?","What should I require from the moving company?"),e("Bohag 2010","Bohag 2010"),e("Branschens allmänna villkor för bohagsflytt, framtagna med Konsumentverket.","The industry's general terms for household moves, drawn up with the Consumer Agency."),e("Ta skriftlig offert, helst fast pris – vid ungefärligt pris får slutpriset bli högst 15 % högre. Välj en firma som följer Bohag 2010 och har yrkestrafiktillstånd (kontrollera hos Transportstyrelsen). Enligt Bohag 2010 kan du avboka gratis fram till 15 dagar före flytten. Flytthjälp och flyttstädning ger rutavdrag på 50 % av arbetskostnaden. Reklamera skador skriftligt; tvister kan prövas av ARN.","Get a written quote, preferably a fixed price – with an approximate price the final cost may be at most 15% higher. Choose a company that follows Bohag 2010 and holds a transport licence (check with Transportstyrelsen). Under Bohag 2010 you can cancel free up to 15 days before the move. Moving help and cleaning qualify for a 50% RUT deduction on labour. Complain about damage in writing; disputes can go to ARN."),e("Du och flyttfirman","You and the moving company"),e("Innan du bokar.","Before you book."),e("Begär fast pris och kontrollera Bohag 2010 och tillstånd","Request a fixed price and check Bohag 2010 and licences"),e("Vad ingår i priset, och hur hanterar ni skador och väntetid?","What is included in the price, and how do you handle damage and waiting time?"),l),n("bredband","common",a.before,e("Kan jag säga upp bredbandet när jag flyttar?","Can I cancel broadband when I move?"),e("Bindningstid","Binding period"),e("Den tid du är bunden att betala för ett abonnemang.","The period you are committed to pay for a subscription."),e("Bindningstiden får vara högst 24 månader och uppsägningstiden högst en månad. Du måste betala bindningstiden ut även om du flyttar och tjänsten inte fungerar på nya adressen; operatören kan kräva resterande period som engångsbelopp. Fråga om flytt av abonnemanget innan du säger upp, och säg upp skriftligt.","The binding period may be at most 24 months and the notice period at most one month. You must pay out the binding period even if you move and the service does not work at the new address; the operator can demand the remaining period as a lump sum. Ask about moving the subscription before cancelling, and cancel in writing."),e("Du och operatören","You and the operator"),e("Så snart flyttdatum är känt.","As soon as the moving date is known."),e("Kontrollera bindningstid och be om flytt av abonnemanget","Check the binding period and ask to move the subscription"),e("Vad kostar det att avsluta i förtid, och finns tjänsten på nya adressen?","What does early termination cost, and is the service available at the new address?"),p),n("barn","common",a.after,e("Hur flyttar jag barnen i folkbokföringen?","How do I register the children's move?"),e("Samtycke till barns flytt","Consent to a child's move"),e("Båda vårdnadshavarnas godkännande av barnets nya folkbokföringsadress.","Both guardians' approval of the child's new registered address."),e("Barn folkbokförs där de sover flest nätter. Flyttar hela familjen anmäler en vårdnadshavare för alla. Bor vårdnadshavarna isär anmäler den barnet bor hos, och den andra lämnar samtycke i e-tjänsten inom sju dagar – annars utreder Skatteverket, vilket tar tid. Skolval och förskola söks separat hos kommunen, där båda vårdnadshavarna normalt ska skriva under.","Children are registered where they sleep most nights. If the whole family moves, one guardian reports for everyone. If guardians live apart, the one the child lives with reports and the other consents in the e-service within seven days – otherwise Skatteverket investigates, which takes time. School and preschool places are applied for separately with the municipality, where both guardians normally sign."),e("Vårdnadshavare och Skatteverket","Guardians and Skatteverket"),e("Senast en vecka efter flytten; samtycke inom sju dagar.","Within a week of the move; consent within seven days."),e("Anmäl barnets flytt och ordna samtycke","Report the child's move and arrange consent"),e("Är vi överens om var barnet ska vara folkbokfört?","Do we agree on where the child should be registered?"),b)],ae=[a.before,a.during,a.access,a.after],ne=[[e("Mellanboende mellan försäljning och köp","Interim home between sale and purchase"),e("Håll alla spår aktiva samtidigt och registrera varje adress och tillträdesdag separat. Räkna med dubbla kostnader, extra flytt och magasin. Säg inte upp din hyresrätt enbart utifrån ett förväntat tillträde – tre kalendermånaders uppsägningstid går inte att korta i efterhand.","Keep all tracks active at once and record each address and completion date separately. Budget for double costs, an extra move and storage. Do not give notice on your rental based only on an expected completion – three calendar months' notice cannot be shortened afterwards.")],[e("Bud och kontrakt är olika saker","Bids and contracts are different things"),e("Inget bud är bindande, och säljaren får välja fritt. Först när båda skrivit under köpekontraktet är affären bindande – och då finns ingen ångerrätt. Lägg aldrig ett bud du inte är beredd att stå för, och be om budgivningslistan efteråt.","No bid is binding, and the seller may choose freely. Only when both have signed the purchase contract is the deal binding – and then there is no cooling-off right. Never bid more than you are prepared to pay, and ask for the bid list afterwards.")],[e("Besiktiga innan, inte efter","Inspect before, not after"),e("Undersökningsplikten är din. En överlåtelsebesiktning täcker sällan el, VVS, skorsten, tomt och radon – beställ tillägg där du har frågor. Hinner besiktningen inte före kontraktet: kräv en besiktningsklausul med tydlig frist och rätt att frånträda utan skäl.","The duty to inspect is yours. A transfer inspection rarely covers electrics, plumbing, chimney, plot and radon – order add-ons where you have questions. If inspection cannot happen before contract: insist on an inspection clause with a clear deadline and the right to withdraw without reasons.")],[e("Bostadsrätt: köp in dig i föreningen, inte bara lägenheten","Bostadsrätt: you are buying into the association, not just the flat"),e("Avgiften styrs av föreningens lån och underhåll. Läs årsredovisning, stadgar och underhållsplan, fråga om stambyte och tak, och be om utdrag ur lägenhetsförteckningen. Köpet fullbordas först när styrelsen beviljat medlemskap.","The fee is driven by the association's loans and maintenance. Read the annual report, bylaws and maintenance plan, ask about pipe and roof work, and get an extract from the apartment register. The purchase is complete only when the board grants membership.")],[e("Lösöre och lovade arbeten","Fixtures and promised work"),e("Skriv exakt vad som ingår – vitvaror, lampor, gardiner, trädgårdsmaskiner – med skick och eventuellt pris. Beskriv arbeten säljaren ska göra, hur de dokumenteras och när. Allt som inte står i kontraktet är svårt att kräva senare.","Write exactly what is included – appliances, lamps, curtains, garden machines – with condition and any price. Describe work the seller will do, how it is documented and when. Anything not in the contract is hard to claim later.")],[e("Tillträde, flyttdag och folkbokföring är tre datum","Completion, moving day and registration are three dates"),e("Tillträdet styr betalning, risk och försäkring. Flyttdagen styr elavtal, eftersändning och städning. Folkbokföringen gäller från den dag du faktiskt flyttar in, om du anmäler inom en vecka. Håll datumen isär i planen.","Completion drives payment, risk and insurance. Moving day drives electricity contracts, mail forwarding and cleaning. Registration applies from the day you actually move in, if reported within a week. Keep the dates apart in your plan.")],[e("Hyresrätt: dokumentera allt","Rental: document everything"),e("Fotografera vid in- och avflyttning, be om besiktningsprotokoll och anmäl skador skriftligt. Hyresvärden måste bevisa skador och kan ställa krav i två år. Normalt slitage betalar du aldrig för.","Photograph at move-in and move-out, ask for inspection protocols and report damage in writing. The landlord must prove damage and can make claims for two years. You never pay for normal wear.")],[e("Två elavtal, en månads framförhållning","Two electricity contracts, one month ahead"),e("Nätavtalet följer bostaden, elhandelsavtalet väljer du. Säg upp båda på gamla adressen – ofta en månad i förväg – och teckna båda på den nya, annars hamnar du på ett dyrare anvisat avtal eller får elen avstängd.","The grid contract follows the home, the supply contract is your choice. End both at the old address – often a month ahead – and sign both at the new one, or you end up on a pricier assigned contract or get disconnected.")],[e("När är vi helt klara?","When are we completely done?"),e("Underskrift, uppfyllda villkor, tillträde, lagfart eller medlemskap, och deklarationen året efter är olika milstolpar. Få bankens eller mäklarens bekräftelse på varje steg. Din markering i appen ändrar inte affärens juridiska status.","Signing, fulfilled conditions, completion, title or membership, and next year's tax return are separate milestones. Get the bank's or agent's confirmation at each step. Your tick in the app does not change the deal's legal status.")]],re={intro:[[e("Fastighetsmäklare","Estate agent"),e("förmedling, budgivning, kontrakt och tillträde – anlitad av säljaren","brokerage, bidding, contract and completion – hired by the seller")],[e("Bank","Bank"),e("lånelöfte, kontantinsats, pantbrev och tillträdesbetalning","loan promise, cash deposit, mortgage deeds and completion payment")],[e("Besiktningsman","Building inspector"),e("bostadens tekniska skick och din undersökningsplikt","the home's technical condition and your duty to inspect")],[e("Jurist / advokat","Lawyer"),e("kontraktsvillkor, friskrivningar, tvister om fel","contract terms, disclaimers, defect disputes")],[e("Hyresgästföreningen","Tenants' Association"),e("hyresavtal, uppsägning, besiktning och tvister med hyresvärd","tenancy contract, notice, inspection and landlord disputes")],[e("Konsumentvägledare","Consumer adviser"),e("kostnadsfri hjälp från kommunen eller Konsumentverket vid tvist med företag","free help from the municipality or the Consumer Agency in disputes with businesses")]],links:[{href:"https://fmi.se/",title:e("Fastighetsmäklarinspektionen","Estate Agents Inspectorate"),description:e("Kontrollera att mäklaren är registrerad och läs vad som gäller vid förmedling","Check that the agent is registered and read the rules for brokerage")},{href:"https://www.konsumentverket.se/varor-och-tjanster/kopa-hus-tips/",title:e("Konsumentverket – köpa hus","Consumer Agency – buying a house"),description:e("Oberoende vägledning om lånelöfte, undersökningsplikt och kontrakt","Independent guidance on loan promise, duty to inspect and contract")},{href:"https://www.konsumentverket.se/varor-och-tjanster/kopa-bostadsratt-tips/",title:e("Konsumentverket – köpa bostadsrätt","Consumer Agency – buying a bostadsrätt"),description:e("Vad du ska granska i föreningen, medlemskap och pantsättning","What to review in the association, membership and pledges")},{href:"https://www.hyresgastforeningen.se/",title:e("Hyresgästföreningen","Tenants' Association"),description:e("Rådgivning om hyresavtal, uppsägning och besiktning för medlemmar","Advice on tenancy, notice and inspection for members")},{href:"https://www.bostadsratterna.se/",title:e("Bostadsrätterna","Bostadsrätterna"),description:e("Kunskapsbank om bostadsrättsföreningar, stadgar och medlemskap","Knowledge base on housing associations, bylaws and membership")},{href:"https://www.konsumenternas.se/",title:e("Konsumenternas","Konsumenternas"),description:e("Oberoende vägledning om bolån, hemförsäkring och bank","Independent guidance on mortgages, home insurance and banking")},{href:"https://www.energimarknadsbyran.se/",title:e("Energimarknadsbyrån","Energy Markets Bureau"),description:e("Oberoende råd om elavtal vid flytt och jämförelse av elpriser","Independent advice on electricity contracts when moving and price comparison")}]};export{te as adviceArticles,ee as adviceReviewed,re as advisers,Q as checklist,z as meta,ae as phases,X as profileOptions,ne as tips,$ as tradeRows,Z as tradeSources};
